import { useMutation, useQuery } from "@tanstack/react-query";
import { CheckCircle2, PlayCircle, RefreshCw } from "lucide-react";
import { useDataProvider, useNotify } from "ra-core";
import { useState } from "react";

import { Button } from "@/components/ui/button";
import { Skeleton } from "@/components/ui/skeleton";

import { formatCurrency } from "../fortnox/invoiceFormat";
import type { CrmDataProvider } from "../providers/types";

const CADENCE: Record<string, string> = {
  monthly: "per månad",
  quarterly: "per kvartal",
  yearly: "per år",
};

type Result = {
  recurringId: string;
  status: string;
  handling: string;
  startDate?: string;
  startsInThePast?: boolean;
  nextInvoiceDate?: string | null;
  activated: boolean;
};

/**
 * Runs the recurring-invoicing flow against the Fortnox test company, so it can
 * be tried on a real deal's figures before anyone points it at a paying
 * customer.
 *
 * It lives here rather than on the deal page for two reasons: the deal page
 * should only ever act on production, and a sandbox run is deliberately not
 * recorded on the deal — the test company's ids would otherwise mark a real
 * deal as already set up and block the genuine one. That is also why the
 * activation step passes the id back explicitly instead of reading it off the
 * deal.
 */
export const FortnoxRecurringSandboxTest = () => {
  const dataProvider = useDataProvider<CrmDataProvider>();
  const notify = useNotify();
  const [dealId, setDealId] = useState<string>("");
  const [result, setResult] = useState<Result | null>(null);

  const { data: deals, isPending } = useQuery({
    queryKey: ["fortnox", "sandbox-test-deals"],
    queryFn: () => dataProvider.getRecurringRevenue(),
  });

  const recurringDeals = (deals ?? []).filter(
    (deal) => (deal.recurring_amount ?? 0) > 0,
  );
  const selected = recurringDeals.find((d) => String(d.id) === dealId);

  const { mutate: create, isPending: isCreating } = useMutation({
    mutationFn: () =>
      dataProvider.createFortnoxRecurringFromDeal(dealId, "sandbox"),
    onSuccess: ({
      recurring_id,
      status,
      invoice_handling,
      start_date,
      next_invoice_date,
      starts_in_the_past,
      warning,
    }) => {
      setResult({
        recurringId: recurring_id,
        status,
        handling: invoice_handling,
        startDate: start_date,
        startsInThePast: starts_in_the_past,
        nextInvoiceDate: next_invoice_date,
        activated: false,
      });
      notify(
        warning ??
          `Avtal upplagt i testmiljön och pausat (${status}). Inget faktureras.`,
        { type: warning ? "warning" : "info" },
      );
    },
    onError: (error: Error) =>
      notify(error.message || "Kunde inte skapa avtalet i testmiljön", {
        type: "error",
      }),
  });

  const { mutate: activate, isPending: isActivating } = useMutation({
    mutationFn: () =>
      dataProvider.activateFortnoxRecurring(
        dealId,
        "sandbox",
        result?.recurringId,
      ),
    onSuccess: ({ status, invoice_handling, next_invoice_date }) => {
      setResult((current) =>
        current
          ? {
              ...current,
              status,
              handling: invoice_handling,
              nextInvoiceDate: next_invoice_date,
              activated: true,
            }
          : current,
      );
      notify(
        next_invoice_date
          ? `Aktiverat i testmiljön. Nästa faktura hade genererats ${next_invoice_date}.`
          : "Aktiverat i testmiljön.",
        { type: "info" },
      );
    },
    onError: (error: Error) =>
      notify(error.message || "Kunde inte aktivera i testmiljön", {
        type: "error",
      }),
  });

  if (isPending) return <Skeleton className="h-24 w-full" />;

  return (
    <div className="space-y-3 rounded-md border p-4">
      <div>
        <h4 className="text-sm font-medium">Testkör avtalsflödet</h4>
        <p className="text-xs text-muted-foreground">
          Kör samma två steg som på deal-sidan, fast mot testföretaget. Affären
          i CRM:et påverkas inte — inget sparas på den.
        </p>
      </div>

      <select
        className="w-full rounded-md border bg-background p-2 text-sm"
        value={dealId}
        onChange={(event) => {
          setDealId(event.target.value);
          setResult(null);
        }}
      >
        <option value="">Välj en vunnen affär med återkommande belopp…</option>
        {recurringDeals.map((deal) => (
          <option key={String(deal.id)} value={String(deal.id)}>
            {deal.company_name ?? "—"} · {deal.name} ·{" "}
            {formatCurrency(deal.recurring_amount ?? 0)}{" "}
            {CADENCE[deal.recurring_interval ?? "monthly"]}
          </option>
        ))}
      </select>

      {selected ? (
        <p className="text-xs text-muted-foreground">
          {selected.invoiced_through
            ? `Fakturerad t.o.m. ${selected.invoiced_through} — avtalet återupptas dagen efter`
            : `Startdatum: ${selected.billing_start_date ?? "saknas, dagens datum används"}`}
        </p>
      ) : null}

      <div className="flex flex-wrap gap-2">
        <Button
          size="sm"
          variant="outline"
          disabled={!dealId || isCreating || Boolean(result)}
          onClick={() => create()}
        >
          <RefreshCw
            className={`mr-2 h-4 w-4 ${isCreating ? "animate-spin" : ""}`}
          />
          1. Skapa pausat avtal
        </Button>
        <Button
          size="sm"
          disabled={!result || result.activated || isActivating}
          onClick={() => activate()}
        >
          <PlayCircle className="mr-2 h-4 w-4" />
          2. Aktivera
        </Button>
        {result ? (
          <Button
            size="sm"
            variant="ghost"
            onClick={() => setResult(null)}
            disabled={isCreating || isActivating}
          >
            Börja om
          </Button>
        ) : null}
      </div>

      {result ? (
        <div className="space-y-1 rounded-md bg-muted/50 p-3 text-xs">
          <div className="flex items-center gap-2 font-medium">
            <CheckCircle2 className="h-3.5 w-3.5 text-emerald-600" />
            {result.activated
              ? "Aktiverat i testmiljön"
              : "Pausat i testmiljön — inget faktureras"}
          </div>
          <div>
            Status: <strong>{result.status}</strong> · hantering:{" "}
            <strong>{result.handling}</strong>
          </div>
          {result.nextInvoiceDate ? (
            <div>
              Första fakturadatum: <strong>{result.nextInvoiceDate}</strong>
              {result.startsInThePast ? (
                <span className="text-destructive">
                  {" "}
                  — bakåt i tiden, kan ge ikapp-fakturor vid aktivering
                </span>
              ) : null}
            </div>
          ) : null}
          <div className="font-mono text-muted-foreground">
            {result.recurringId}
          </div>
        </div>
      ) : null}
    </div>
  );
};

import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import {
  AlertTriangle,
  CheckCircle2,
  ExternalLink,
  FlaskConical,
} from "lucide-react";
import { useDataProvider, useNotify } from "ra-core";

import { Alert, AlertDescription, AlertTitle } from "@/components/ui/alert";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Skeleton } from "@/components/ui/skeleton";

import type { CrmDataProvider } from "../providers/types";
import type { FortnoxEnvironment } from "../types";
import { FortnoxRecurringSandboxTest } from "./FortnoxRecurringSandboxTest";

/**
 * One Fortnox connection. The consent flow runs once per company: it creates a
 * service account in Fortnox, after which the backend mints its own tokens and
 * nobody has to log in again.
 *
 * Production and sandbox are separate connections, stored as separate rows, so
 * authorizing a test company never disturbs the live one — which matters
 * because the invoice sync runs every 15 minutes and would otherwise pull
 * invented invoices into the mirror that Kundtäckning and Likviditet read.
 */
const ConnectionPanel = ({
  environment,
}: {
  environment: FortnoxEnvironment;
}) => {
  const dataProvider = useDataProvider<CrmDataProvider>();
  const notify = useNotify();
  const queryClient = useQueryClient();
  const isSandbox = environment === "sandbox";

  const { data: status, isPending } = useQuery({
    queryKey: ["fortnox", "status", environment],
    queryFn: () => dataProvider.getFortnoxStatus(environment),
    retry: false,
  });

  const { mutate: connect, isPending: isConnecting } = useMutation({
    // Reconnecting replaces the stored connection, so the backend requires the
    // caller to say so explicitly.
    mutationFn: () =>
      dataProvider.startFortnoxAuthorization(
        status?.connected === true,
        environment,
      ),
    onSuccess: ({ authorization_url }) => {
      // Fortnox demands a real browser login, so we hand the user off to it.
      window.open(authorization_url, "_blank", "noopener,noreferrer");
      notify(
        isSandbox
          ? "Logga in på testföretaget i Fortnox-fönstret och godkänn kopplingen, uppdatera sedan sidan."
          : "Godkänn kopplingen i Fortnox-fönstret, uppdatera sedan sidan.",
        { type: "info" },
      );
    },
    onError: () => {
      notify("Kunde inte starta Fortnox-kopplingen", { type: "error" });
    },
    onSettled: () => {
      queryClient.invalidateQueries({ queryKey: ["fortnox", "status"] });
    },
  });

  return (
    <div className="space-y-4">
      {isPending ? (
        <Skeleton className="h-16 w-full" />
      ) : status?.connected ? (
        <div className="space-y-2 text-sm">
          <p>
            Anslutet till <strong>{status.company_name ?? "Fortnox"}</strong>
            {status.org_number ? ` (${status.org_number})` : ""}.
          </p>
          {status.auth_mode === "refresh_token" ? (
            <Alert variant="destructive">
              <AlertTriangle className="h-4 w-4" />
              <AlertTitle>Kopplingen är inte permanent</AlertTitle>
              <AlertDescription>
                Inget servicekonto kunde skapas, så kopplingen vilar på en
                refresh-token som slutar gälla efter 45 dagars inaktivitet.
                Koppla om för att försöka igen.
              </AlertDescription>
            </Alert>
          ) : (
            <p className="text-muted-foreground">
              Servicekonto aktivt — kopplingen förnyar sig själv och behöver
              aldrig loggas in på nytt.
            </p>
          )}
        </div>
      ) : (
        <div className="space-y-2 text-sm">
          <p className="text-muted-foreground">
            {isSandbox
              ? "Skapa en testmiljö i Fortnox utvecklarportal, koppla den här och prova nya flöden mot den i stället för mot skarp bokföring."
              : "Koppla CRM:et till Fortnox för att kunna skapa kunder och fakturor och följa betalstatus direkt härifrån."}
          </p>
          {status?.error ? (
            <Alert variant="destructive">
              <AlertTriangle className="h-4 w-4" />
              <AlertTitle>Fortnox svarade med ett fel</AlertTitle>
              <AlertDescription>{status.error}</AlertDescription>
            </Alert>
          ) : null}
        </div>
      )}

      <Button
        onClick={() => connect()}
        disabled={isConnecting}
        variant={status?.connected || isSandbox ? "outline" : "default"}
      >
        <ExternalLink className="mr-2 h-4 w-4" />
        {status?.connected
          ? "Koppla om"
          : isSandbox
            ? "Koppla testmiljö"
            : "Koppla till Fortnox"}
      </Button>
    </div>
  );
};

