                  _: "Dessa fält skickas till DocuSeal när du trycker Skicka för signering. Kontrollera att allt stämmer.",
                },
              )}
            </DialogDescription>
          </DialogHeader>
          <div className="space-y-3 mt-2">
            {fields.map((field) => (
              <div key={field.name} className="border rounded-md p-3">
