  async getQuotePipelineSteps(quoteId: Identifier): Promise<
    Array<{
      id: number;
      quote_id: number;
      step_name: string;
      status: "running" | "success" | "failed" | "skipped";
      started_at: string;
      completed_at: string | null;
      duration_ms: number | null;
      error_message: string | null;
