/**
 * Maps parsed headers to canonical CRM field names using aliases.
 * Returns a mapping from original header → canonical name.
 */
export function mapHeadersToCanonical(
  headers: string[],
): Record<string, string> {
  const mapping: Record<string, string> = {};

  for (const header of headers) {
    const normalized = header.toLowerCase().replace(/[\s-]+/g, "_");

    // Direct match — header is already canonical
    if (COLUMN_ALIASES[normalized]) {
      mapping[header] = COLUMN_ALIASES[normalized];
    } else if (
      [
        "first_name",
        "last_name",
        "company",
        "phone_work",
        "email_work",
        "tags",
        "title",
        "gender",
        "background",
        "linkedin_url",
        "website",
        "address",
        "city",
        "zipcode",
        "country",
        "avatar",
        "has_newsletter",
        "status",
        "phone_home",
        "phone_other",
        "email_home",
        "email_other",
        "first_seen",
        "last_seen",
      ].includes(normalized)
    ) {
      mapping[header] = normalized;
    } else {
      // Keep unmapped columns as-is (will be ignored during import)
      mapping[header] = normalized;
    }
  }

  return mapping;
}

/**
 * Remaps rows using the canonical column mapping.
 */
export function remapRows(
  rows: ParsedRow[],
  headers: string[],
  mapping: Record<string, string>,
): ParsedRow[] {
  return rows.map((row) => {
    const mapped: ParsedRow = {};
    for (const header of headers) {
      const canonical = mapping[header] ?? header;
      mapped[canonical] = row[header] ?? "";
    }
    return mapped;
  });
}

const LINKEDIN_URL_REGEX = /^http(?:s)?:\/\/(?:www\.)?linkedin.com\//;

export const isLinkedinUrl = (url: string) => {
  if (!url) return;
  try {
    // Parse the URL to ensure it is valid
    const parsedUrl = new URL(url);
    if (!parsedUrl.href.match(LINKEDIN_URL_REGEX)) {
      return {
        message: "crm.validation.invalid_linkedin_url",
        args: { _: "URL must be from linkedin.com" },
      };
    }
  } catch {
    // If URL parsing fails, return false
    return {
      message: "crm.validation.invalid_url",
      args: { _: "Must be a valid URL" },
    };
  }
};

type FetchParams = Parameters<typeof fetch>;

export async function fetchWithTimeout(
  resource: string,
  options: FetchParams[1] & { timeout?: number } = {},
) {
  const { timeout = 2000 } = options;

  const controller = new AbortController();
  const id = setTimeout(() => controller.abort(), timeout);

  const response = await fetch(resource, {
    ...options,
    signal: controller.signal,
  });

  clearTimeout(id);

  return response;
}

