              value={orgForms}
              onChange={(e) => setOrgForms(e.target.value)}
            />
            <p className="text-muted-foreground text-xs">
              Kommaseparerade. Matchar delsträngar i organisationsform (ej
              skiftlägeskänsligt).
            </p>
          </div>

          {/* Include verksamhet */}
