    queryFn: () => dataProvider.getSubscriptions(),
  });

  const { data: costs } = useQuery({
    queryKey: ["fortnox", "cost-by-description"],
    queryFn: () => dataProvider.getCostByDescription(),
  });

  const costRows: CostRow[] = useMemo(
    () =>
      (costs ?? []).map((c) => ({
        description: c.description,
        month_count: c.month_count,
        total_cost: c.total_cost,
        cost_90d: c.cost_90d,
        last_date: c.last_date,
      })),
    [costs],
  );

  const endMutation = useMutation({
    mutationFn: (id: Subscription["id"]) =>
      dataProvider.updateSubscription(id, {
        status: "ended",
        ended_on: new Date().toISOString().slice(0, 10),
      }),
    onSuccess: () => {
      notify("Abonnemang avslutat", { type: "info" });
      queryClient.invalidateQueries({ queryKey: ["subscriptions"] });
    },
  });

  const deleteMutation = useMutation({
    mutationFn: (id: Subscription["id"]) => dataProvider.deleteSubscription(id),
    onSuccess: () => {
      notify("Abonnemang borttaget", { type: "info" });
      queryClient.invalidateQueries({ queryKey: ["subscriptions"] });
    },
  });

  const enriched = useMemo(
    () =>
      (subscriptions ?? []).map((s) => {
        const rec = reconcile(s.aliases, costRows);
        return { s, rec, dev: deviation(s.monthly_amount, rec) };
      }),
    [subscriptions, costRows],
  );

  const active = enriched.filter((e) => e.s.status === "active");
  const history = enriched.filter((e) => e.s.status !== "active");

  const declaredMonthly = active.reduce(
    (sum, e) => sum + e.s.monthly_amount,
    0,
  );
  const bookedMonthly = active.reduce((sum, e) => sum + e.rec.bookedMonthly, 0);
  const deviations = active.filter((e) => e.dev !== "ok").length;

  const unregistered = useMemo(
    () => findUnregistered(costRows, subscriptions ?? []),
    [costRows, subscriptions],
  );

  const openCreate = (seedValue?: { name: string; aliases: string }) => {
    setEditing(undefined);
    setSeed(seedValue);
    setDialogOpen(true);
  };
  const openEdit = (s: Subscription) => {
    setEditing(s);
    setSeed(undefined);
    setDialogOpen(true);
  };

  const DevBadge = ({
    dev,
    booked,
  }: {
    dev: ReturnType<typeof deviation>;
    booked: number;
  }) => {
    if (dev === "ok") return null;
    if (dev === "missing") {
      return <Badge variant="outline">ej bokförd senaste 90 dgr</Badge>;
    }
    return (
      <Badge variant="destructive">bokfört ~{formatCurrency(booked)}/mån</Badge>
    );
  };

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-semibold">Abonnemang</h1>
          <p className="text-sm text-muted-foreground">
            Det ni faktiskt betalar för — stämt av mot bokföringen.
          </p>
        </div>
        <Button onClick={() => openCreate()}>
          <Plus className="mr-2 h-4 w-4" />
          Lägg till
        </Button>
      </div>

      <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-4">
        <StatCard
          label="Löpande kostnad"
          value={`${formatCurrency(declaredMonthly)}/mån`}
          sub={`${active.length} aktiva abonnemang`}
        />
        <StatCard
          label="Bokfört (~90 dgr)"
          value={`${formatCurrency(bookedMonthly)}/mån`}
          sub="vad Fortnox faktiskt dragit"
        />
        <StatCard
          label="Avvikelser"
          value={String(deviations)}
          sub="deklarerat ≠ bokfört"
          tone={deviations > 0 ? "danger" : undefined}
        />
        <StatCard
          label="Oregistrerade"
          value={String(unregistered.length)}
          sub="återkommande i bokföringen"
          tone={unregistered.length > 0 ? "danger" : undefined}
        />
      </div>

      <Card>
        <CardContent className="p-0">
          <div className="p-4 pb-0">
            <h2 className="font-semibold">Aktiva abonnemang</h2>
          </div>
          {active.length === 0 ? (
            <p className="p-6 text-sm text-muted-foreground">
              Inga aktiva abonnemang. Klicka "Lägg till".
            </p>
          ) : (
            <Table>
              <TableHeader>
                <TableRow>
                  <TableHead>Namn</TableHead>
                  <TableHead>Kategori</TableHead>
                  <TableHead className="text-right">Deklarerat/mån</TableHead>
                  <TableHead className="text-right">Bokfört/mån</TableHead>
                  <TableHead>Sedan</TableHead>
                  <TableHead className="w-10" />
                </TableRow>
              </TableHeader>
              <TableBody>
                {active.map(({ s, rec, dev }) => (
                  <TableRow key={s.id}>
                    <TableCell className="font-medium">{s.name}</TableCell>
                    <TableCell className="text-muted-foreground">
                      {s.category ?? "—"}
                    </TableCell>
                    <TableCell className="text-right">
                      {formatCurrency(s.monthly_amount)}
                    </TableCell>
                    <TableCell className="text-right">
                      <div className="flex flex-col items-end gap-1">
                        <span>{formatCurrency(rec.bookedMonthly)}</span>
                        <DevBadge dev={dev} booked={rec.bookedMonthly} />
                      </div>
                    </TableCell>
                    <TableCell>{formatDate(s.started_on)}</TableCell>
                    <TableCell>
                      <DropdownMenu>
                        <DropdownMenuTrigger asChild>
                          <Button variant="ghost" size="icon">
                            <MoreVertical className="h-4 w-4" />
                          </Button>
                        </DropdownMenuTrigger>
                        <DropdownMenuContent align="end">
                          <DropdownMenuItem onClick={() => openEdit(s)}>
                            Redigera
                          </DropdownMenuItem>
                          <DropdownMenuItem
                            onClick={() => endMutation.mutate(s.id)}
                          >
                            Avsluta
                          </DropdownMenuItem>
                          <DropdownMenuItem
                            className="text-destructive"
                            onClick={() => deleteMutation.mutate(s.id)}
                          >
                            Ta bort
                          </DropdownMenuItem>
                        </DropdownMenuContent>
                      </DropdownMenu>
                    </TableCell>
                  </TableRow>
                ))}
              </TableBody>
            </Table>
          )}
        </CardContent>
      </Card>

      {unregistered.length > 0 ? (
        <Card>
          <CardContent className="p-0">
            <div className="p-4 pb-0">
              <h2 className="font-semibold">
                Återkommande i bokföringen — ej i registret
              </h2>
              <p className="text-sm text-muted-foreground">
                Kostnader som dras löpande men saknas i listan ovan. Lägg till
                dem så fångas de i runraten.
              </p>
            </div>
            <Table>
              <TableHeader>
                <TableRow>
                  <TableHead>Leverantör (bokföring)</TableHead>
                  <TableHead className="text-right">~/mån (90 dgr)</TableHead>
                  <TableHead>Senast</TableHead>
                  <TableHead className="w-24" />
                </TableRow>
              </TableHeader>
              <TableBody>
                {unregistered.map((c) => (
                  <TableRow key={c.description}>
                    <TableCell className="font-mono text-xs">
                      {c.description}
                    </TableCell>
                    <TableCell className="text-right">
                      {formatCurrency(c.cost_90d / 3)}
                    </TableCell>
                    <TableCell>{formatDate(c.last_date)}</TableCell>
                    <TableCell className="text-right">
                      <Button
                        size="sm"
                        variant="outline"
                        onClick={() =>
                          openCreate({
                            name: c.description,
                            aliases: c.description,
                          })
                        }
                      >
                        Lägg till
                      </Button>
                    </TableCell>
                  </TableRow>
                ))}
              </TableBody>
            </Table>
          </CardContent>
        </Card>
      ) : null}

      {history.length > 0 ? (
        <Card>
          <CardContent className="p-0">
            <div className="p-4 pb-0">
              <h2 className="font-semibold">Tidigare &amp; pausade</h2>
            </div>
            <Table>
              <TableHeader>
                <TableRow>
                  <TableHead>Namn</TableHead>
                  <TableHead>Status</TableHead>
                  <TableHead>Period</TableHead>
                  <TableHead className="text-right">Deklarerat/mån</TableHead>
                  <TableHead className="w-10" />
                </TableRow>
              </TableHeader>
              <TableBody>
                {history.map(({ s }) => (
                  <TableRow key={s.id}>
                    <TableCell className="font-medium">{s.name}</TableCell>
                    <TableCell>
                      <Badge variant="outline">
                        {s.status === "ended" ? "Avslutad" : "Pausad"}
                      </Badge>
                    </TableCell>
                    <TableCell className="text-muted-foreground">
                      {formatDate(s.started_on)} – {formatDate(s.ended_on)}
                    </TableCell>
                    <TableCell className="text-right">
                      {formatCurrency(s.monthly_amount)}
                    </TableCell>
                    <TableCell>
                      <DropdownMenu>
                        <DropdownMenuTrigger asChild>
                          <Button variant="ghost" size="icon">
                            <MoreVertical className="h-4 w-4" />
                          </Button>
                        </DropdownMenuTrigger>
                        <DropdownMenuContent align="end">
                          <DropdownMenuItem onClick={() => openEdit(s)}>
                            Redigera
                          </DropdownMenuItem>
                          <DropdownMenuItem
                            className="text-destructive"
                            onClick={() => deleteMutation.mutate(s.id)}
                          >
                            Ta bort
                          </DropdownMenuItem>
                        </DropdownMenuContent>
                      </DropdownMenu>
                    </TableCell>
                  </TableRow>
                ))}
              </TableBody>
            </Table>
          </CardContent>
        </Card>
      ) : null}

      <p className="text-xs text-muted-foreground">
        "Bokfört/mån" är vad Fortnox faktiskt dragit senaste 90 dagarna
        (återbetalningar avräknade), fördelat per månad. Avviker det mycket från
        det deklarerade beloppet är det värt att kolla.
      </p>

      <SubscriptionDialog
        open={dialogOpen}
        onOpenChange={setDialogOpen}
        subscription={editing}
        seed={seed}
      />
    </div>
  );
};

SubscriptionsPage.path = "/subscriptions";

import { useMutation, useQueryClient } from "@tanstack/react-query";
import { useDataProvider, useNotify } from "ra-core";
import { useEffect, useState } from "react";

import { Button } from "@/components/ui/button";
import {
  Dialog,
  DialogContent,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { Textarea } from "@/components/ui/textarea";

import type { CrmDataProvider } from "../providers/types";
import type { Subscription, SubscriptionInput } from "../types";

const CATEGORIES = [
  "AI-verktyg",
  "Hosting/Infra",
  "Design",
  "Produktivitet",
  "Bank/Ekonomi",
  "Övrigt",
];

const STATUS_OPTIONS: { value: Subscription["status"]; label: string }[] = [
  { value: "active", label: "Aktiv" },
  { value: "paused", label: "Pausad" },
  { value: "ended", label: "Avslutad" },
];

const parseAliases = (raw: string): string[] =>
  raw
    .split(",")
    .map((a) => a.trim().toUpperCase())
    .filter((a) => a.length > 0);

type FormState = {
  name: string;
  category: string;
  monthly_amount: string;
  status: Subscription["status"];
  started_on: string;
  ended_on: string;
  aliases: string;
  notes: string;
};

const emptyForm = (seed?: Partial<FormState>): FormState => ({
  name: "",
  category: "AI-verktyg",
  monthly_amount: "",
  status: "active",
  started_on: "",
  ended_on: "",
  aliases: "",
  notes: "",
  ...seed,
});

const fromSubscription = (s: Subscription): FormState => ({
  name: s.name,
  category: s.category ?? "Övrigt",
  monthly_amount: String(s.monthly_amount),
  status: s.status,
  started_on: s.started_on ?? "",
  ended_on: s.ended_on ?? "",
  aliases: s.aliases.join(", "),
  notes: s.notes ?? "",
});

/**
 * Add or edit a subscription in the manual registry. Edit mode is entered by
 * passing `subscription`; `seed` prefills a create form (used by the
 * "unregistered cost → add" shortcut).
 */
export const SubscriptionDialog = ({
  open,
  onOpenChange,
  subscription,
  seed,
}: {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  subscription?: Subscription;
  seed?: Partial<FormState>;
}) => {
  const dataProvider = useDataProvider<CrmDataProvider>();
  const notify = useNotify();
  const queryClient = useQueryClient();
  const [form, setForm] = useState<FormState>(emptyForm(seed));

  useEffect(() => {
    if (open) {
      setForm(subscription ? fromSubscription(subscription) : emptyForm(seed));
    }
  }, [open, subscription, seed]);

  const set = <K extends keyof FormState>(key: K, value: FormState[K]) =>
    setForm((prev) => ({ ...prev, [key]: value }));

  const { mutate, isPending } = useMutation({
    mutationFn: () => {
      const input: SubscriptionInput = {
        name: form.name.trim(),
        category: form.category,
        monthly_amount: Number(form.monthly_amount) || 0,
        status: form.status,
        started_on: form.started_on || null,
        ended_on: form.ended_on || null,
        aliases: parseAliases(form.aliases),
        notes: form.notes.trim() || null,
      };
      return subscription
        ? dataProvider.updateSubscription(subscription.id, input)
        : dataProvider.createSubscription(input);
    },
    onSuccess: () => {
      notify(subscription ? "Abonnemang uppdaterat" : "Abonnemang tillagt", {
        type: "info",
      });
      queryClient.invalidateQueries({ queryKey: ["subscriptions"] });
      onOpenChange(false);
    },
    onError: () => notify("Kunde inte spara abonnemanget", { type: "error" }),
  });

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="max-h-[90vh] overflow-y-auto sm:max-w-lg">
        <DialogHeader>
          <DialogTitle>
            {subscription ? "Redigera abonnemang" : "Nytt abonnemang"}
          </DialogTitle>
        </DialogHeader>

        <div className="space-y-4">
          <div className="space-y-1.5">
            <Label htmlFor="sub-name">Namn / plan</Label>
            <Input
              id="sub-name"
              value={form.name}
              onChange={(e) => set("name", e.target.value)}
              placeholder="Claude Max"
            />
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-1.5">
              <Label htmlFor="sub-amount">Kostnad / månad (kr)</Label>
              <Input
                id="sub-amount"
                type="number"
                inputMode="decimal"
                value={form.monthly_amount}
                onChange={(e) => set("monthly_amount", e.target.value)}
                placeholder="350"
              />
            </div>
            <div className="space-y-1.5">
              <Label>Kategori</Label>
              <Select
                value={form.category}
                onValueChange={(v) => set("category", v)}
              >
                <SelectTrigger>
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  {CATEGORIES.map((c) => (
                    <SelectItem key={c} value={c}>
                      {c}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
          </div>

          <div className="grid grid-cols-3 gap-4">
            <div className="space-y-1.5">
              <Label>Status</Label>
              <Select
                value={form.status}
                onValueChange={(v) =>
                  set("status", v as Subscription["status"])
                }
              >
                <SelectTrigger>
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  {STATUS_OPTIONS.map((s) => (
                    <SelectItem key={s.value} value={s.value}>
                      {s.label}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
            <div className="space-y-1.5">
              <Label htmlFor="sub-start">Startdatum</Label>
              <Input
                id="sub-start"
                type="date"
                value={form.started_on}
                onChange={(e) => set("started_on", e.target.value)}
              />
            </div>
            <div className="space-y-1.5">
              <Label htmlFor="sub-end">Slutdatum</Label>
              <Input
                id="sub-end"
                type="date"
                value={form.ended_on}
                onChange={(e) => set("ended_on", e.target.value)}
              />
            </div>
          </div>

          <div className="space-y-1.5">
            <Label htmlFor="sub-aliases">Alias (matchar bokföringen)</Label>
            <Input
              id="sub-aliases"
              value={form.aliases}
              onChange={(e) => set("aliases", e.target.value)}
              placeholder="CHATGPT, OPENAI *CHATGPT"
            />
            <p className="text-xs text-muted-foreground">
              Kommaseparerat. Textmönster som matchar leverantörens rader i
              bokföringen för avstämning.
            </p>
          </div>

          <div className="space-y-1.5">
            <Label htmlFor="sub-notes">Anteckning</Label>
            <Textarea
              id="sub-notes"
              value={form.notes}
              onChange={(e) => set("notes", e.target.value)}
              rows={2}
            />
          </div>
        </div>

        <DialogFooter>
          <Button variant="outline" onClick={() => onOpenChange(false)}>
            Avbryt
          </Button>
          <Button
            onClick={() => mutate()}
            disabled={isPending || form.name.trim().length === 0}
          >
            Spara
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
};

import { useMutation, useQueryClient } from "@tanstack/react-query";
import { ExternalLink, PlayCircle, RefreshCw } from "lucide-react";
import {
  useDataProvider,
  useNotify,
  useRecordContext,
  useRefresh,
} from "ra-core";
import { useState } from "react";

import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";

import type { CrmDataProvider } from "../providers/types";
import type { Deal } from "../types";
import { formatCurrency } from "./invoiceFormat";

const INTERVAL_LABELS: Record<string, string> = {
  monthly: "per månad",
  quarterly: "per kvartal",
  yearly: "per år",
};

/**
 * Sets up "Återkommande fakturering" in Fortnox for a won recurring deal, in
 * two deliberate steps.
 *
 * Creating parks the recurring as paused with manual handling — visible and
 * checkable in Fortnox, but billing nobody for two independent reasons.
 * Activating is a separate button that starts the invoicing, so it confirms
 * first and says so plainly.
 *
 * It is paused rather than a draft because Fortnox has no "create a draft" API
 * input and refuses to move an activated recurring back to DRAFT. Paused is the
 * reachable equivalent: "retained but not generating invoices".
 */
export const RecurringDealButton = () => {
  const deal = useRecordContext<Deal>();
  const dataProvider = useDataProvider<CrmDataProvider>();
  const notify = useNotify();
  const refresh = useRefresh();
  const queryClient = useQueryClient();
  const [confirmingActivate, setConfirmingActivate] = useState(false);

  const settled = () => {
    queryClient.invalidateQueries({ queryKey: ["fortnox"] });
    refresh();
  };

  const { mutate: create, isPending: isCreating } = useMutation({
    mutationFn: () => dataProvider.createFortnoxRecurringFromDeal(deal!.id),
    onSuccess: ({ warning }) => {
      notify(
        warning ??
          "Återkommande fakturering upplagd i Fortnox och pausad — granska den där, inga fakturor skickas förrän du aktiverar.",
        { type: warning ? "warning" : "info" },
      );
      settled();
    },
    onError: (error: Error) =>
      notify(error.message || "Kunde inte lägga upp återkommande fakturering", {
        type: "error",
      }),
  });

  const { mutate: activate, isPending: isActivating } = useMutation({
    mutationFn: () => dataProvider.activateFortnoxRecurring(deal!.id),
    onSuccess: ({ next_invoice_date }) => {
      setConfirmingActivate(false);
      notify(
        next_invoice_date
          ? `Återkommande fakturering aktiverad. Nästa faktura genereras ${next_invoice_date}.`
          : "Återkommande fakturering aktiverad. Fortnox genererar fakturorna enligt schemat.",
        { type: "info" },
      );
      settled();
    },
    onError: (error: Error) => {
      setConfirmingActivate(false);
      notify(error.message || "Kunde inte aktivera faktureringen", {
        type: "error",
      });
    },
  });

  if (!deal) return null;

  const amount = deal.recurring_amount ?? 0;
  if (deal.stage !== "won" || amount <= 0) return null;

  const cadence = INTERVAL_LABELS[deal.recurring_interval ?? "monthly"];
  const status = deal.fortnox_recurring_status;

  if (!deal.fortnox_recurring_id) {
    return (
      <Button
        size="sm"
        variant="outline"
        onClick={() => create()}
        disabled={isCreating}
        title="Lägger upp återkommande fakturering i Fortnox, pausad — inga fakturor skickas"
      >
        <RefreshCw
          className={`mr-2 h-4 w-4 ${isCreating ? "animate-spin" : ""}`}
        />
        Lägg upp återkommande
      </Button>
    );
  }

  if (status === "ACTIVE") {
    return (
      <div className="flex items-center gap-2">
        <Badge variant="secondary">
          Återkommande aktiv · {formatCurrency(amount)} {cadence}
        </Badge>
        <Button size="sm" variant="ghost" asChild>
          <a href="/#/invoices">
            <ExternalLink className="mr-2 h-3 w-3" />
            Fakturor
          </a>
        </Button>
      </div>
    );
  }

  if (status === "FINISHED") {
    return <Badge variant="outline">Återkommande avslutad i Fortnox</Badge>;
  }

  // Paused (our review state), or a status we haven't refreshed: offer to start.
  return (
    <>
      <div className="flex items-center gap-2">
        <Badge variant="outline">Återkommande: ej aktiverad</Badge>
        <Button
          size="sm"
          onClick={() => setConfirmingActivate(true)}
          disabled={isActivating}
          title="Startar den återkommande faktureringen i Fortnox"
        >
          <PlayCircle className="mr-2 h-4 w-4" />
          Aktivera
        </Button>
      </div>

      <Dialog open={confirmingActivate} onOpenChange={setConfirmingActivate}>
        <DialogContent>
          <DialogHeader>
            <DialogTitle>
              Aktivera återkommande fakturering på {formatCurrency(amount)}{" "}
              {cadence}?
            </DialogTitle>
            <DialogDescription asChild>
              <div className="space-y-2 text-sm">
                <p>
                  Fortnox börjar generera fakturor för{" "}
                  <strong>{deal.name}</strong> enligt schemat. Det här är steget
                  som faktiskt börjar fakturera kunden.
                </p>
                <p>
                  Kontrollera avtalet i Fortnox först om du inte redan gjort det
                  — belopp, startdatum och faktureringsintervall.
                </p>
              </div>
            </DialogDescription>
          </DialogHeader>
          <DialogFooter>
            <Button
              variant="ghost"
              onClick={() => setConfirmingActivate(false)}
              disabled={isActivating}
            >
              Avbryt
            </Button>
            <Button onClick={() => activate()} disabled={isActivating}>
              {isActivating ? "Aktiverar…" : "Aktivera fakturering"}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </>
  );
};

