import { Badge } from "@/components/ui/badge";

import type { FortnoxInvoice } from "../types";
import { daysOverdue, isUnsentAndActionable } from "./invoiceFormat";

/**
 * The one place invoice status is rendered. Used on the Fakturor page and on
 * the customer card, so the two can never tell different stories.
 *
 * The send badge says "via Fortnox" on purpose. Fortnox's `Sent` flag only
 * knows about its own sender — an invoice emailed by hand looks unsent forever,
 * which is why 5 of the 7 "unsent" invoices in the tenant were already paid.
 * It is shown only where it is actionable: on an unpaid invoice.
 */
export const InvoiceStatusBadge = ({
  invoice,
  showSent = true,
}: {
  invoice: Pick<FortnoxInvoice, "status" | "due_date" | "sent">;
  showSent?: boolean;
}) => {
  const overdue = daysOverdue(invoice.due_date);

  return (
    <div className="flex flex-wrap items-center gap-1">
      {invoice.status === "overdue" ? (
        <Badge variant="destructive">
          Förfallen{overdue ? ` · ${overdue} d` : ""}
        </Badge>
      ) : invoice.status === "paid" ? (
        <Badge variant="outline" className="border-green-600 text-green-700">
          Betald
        </Badge>
      ) : invoice.status === "cancelled" ? (
        <Badge variant="secondary">Makulerad</Badge>
      ) : (
        <Badge variant="secondary">Obetald</Badge>
      )}

      {showSent && isUnsentAndActionable(invoice) ? (
        <Badge variant="outline">Ej skickad via Fortnox</Badge>
      ) : null}
    </div>
  );
};

import { useMutation, useQueryClient } from "@tanstack/react-query";
import { ExternalLink, Receipt } from "lucide-react";
import {
  useDataProvider,
  useNotify,
  useRecordContext,
  useRefresh,
} from "ra-core";

import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";

import type { CrmDataProvider } from "../providers/types";
import type { Quote } from "../types";

type QuoteWithInvoice = Quote & { fortnox_invoice_number?: number | null };

/**
 * Creates an invoice in Fortnox from this quote.
 *
 * The invoice is created UNBOOKED and UNSENT — a draft. Sending it is a
 * separate, deliberate action on the Fakturor page. Nothing here touches the
 * accounting record.
 *
 * A quote can only be invoiced once; the database enforces it, and the button
 * turns into a link to the invoice afterwards.
 */
export const InvoiceQuoteButton = () => {
  const quote = useRecordContext<QuoteWithInvoice>();
  const dataProvider = useDataProvider<CrmDataProvider>();
  const notify = useNotify();
  const refresh = useRefresh();
  const queryClient = useQueryClient();

  const { mutate, isPending } = useMutation({
    mutationFn: () => dataProvider.createFortnoxInvoiceFromQuote(quote!.id),
    onSuccess: ({ document_number }) => {
      notify(
        `Fakturautkast ${document_number} skapat i Fortnox. Den är varken bokförd eller skickad.`,
        { type: "info" },
      );
      queryClient.invalidateQueries({ queryKey: ["fortnox"] });
      refresh();
    },
    onError: (error: Error) =>
      notify(error.message || "Kunde inte skapa fakturan", { type: "error" }),
  });

  if (!quote) return null;

  if (quote.fortnox_invoice_number) {
    return (
      <div className="flex items-center gap-2">
        <Badge variant="outline">
          Fakturerad · {quote.fortnox_invoice_number}
        </Badge>
        <Button size="sm" variant="ghost" asChild>
          <a href="/#/invoices">
            <ExternalLink className="mr-2 h-3 w-3" />
            Visa faktura
          </a>
        </Button>
      </div>
    );
  }

  // Invoicing an unsigned quote is almost always a mistake, so make the user
  // sign it (or say so out loud) first.
  const canInvoice = quote.status === "signed";

  return (
    <Button
      size="sm"
      variant="outline"
      onClick={() => mutate()}
      disabled={isPending || !canInvoice}
      title={
        canInvoice
          ? "Skapar ett obokfört fakturautkast i Fortnox"
          : "Offerten måste vara signerad innan den kan faktureras"
      }
    >
      <Receipt className="mr-2 h-4 w-4" />
      Fakturera
    </Button>
  );
};

