 * until a human books and sends it. What this button really buys is the link:
 * the invoice carries the deal reference, so Kundtäckning stops having to guess
 * which invoice belongs to which deal from the amount alone.
 *
 * A deal split into installments is billed one part at a time: the button offers
 * the next part, and the amount comes from the deal total divided by the number
 * of parts (the last part absorbs any rounding remainder). Everything else is
 * invoiced in full, once. Both cases are guarded in the database, so a double
 * click can't bill the customer twice, and the button turns into a badge once
 * there is nothing left to invoice.
 */
export const InvoiceDealButton = () => {
  const deal = useRecordContext<Deal>();
  const dataProvider = useDataProvider<CrmDataProvider>();
  const notify = useNotify();
  const refresh = useRefresh();
  const queryClient = useQueryClient();
  const [confirming, setConfirming] = useState(false);

  const { mutate, isPending } = useMutation({
    mutationFn: () => dataProvider.createFortnoxInvoiceFromDeal(deal!.id),
    onSuccess: ({ document_number, installment_index, installment_count }) => {
      setConfirming(false);
      notify(
        installment_index
          ? `Delfaktura ${installment_index}/${installment_count} skapad i Fortnox (nr ${document_number}) som utkast — inget är bokfört eller skickat än.`
          : `Faktura ${document_number} skapad i Fortnox som utkast — inget är bokfört eller skickat än.`,
        { type: "info" },
      );
      queryClient.invalidateQueries({ queryKey: ["fortnox"] });
      refresh();
    },
    onError: (error: Error) => {
      setConfirming(false);
      notify(error.message || "Kunde inte skapa fakturan", { type: "error" });
    },
  });

  if (!deal) return null;

  const total = deal.amount ?? 0;
  if (deal.stage !== "won" || total <= 0) return null;

  const partCount = deal.installment_count ?? 0;
  const isInstallment =
    deal.billing_schedule_type === "installment" && partCount > 0;
  const invoicedParts = deal.installments_invoiced ?? 0;
  const partIndex = invoicedParts + 1;

  // The part amount, with the last part absorbing the rounding remainder —
  // mirrors installmentAmount in the edge function so the dialog promises the
  // figure that will actually be invoiced.
  const perPart = Math.round((total / (partCount || 1)) * 100) / 100;
  const partAmount =
    partIndex < partCount
      ? perPart
      : Math.round((total - perPart * (partCount - 1)) * 100) / 100;
  const amountToInvoice = isInstallment ? partAmount : total;

  const allPartsInvoiced = isInstallment && invoicedParts >= partCount;

  if (allPartsInvoiced) {
    return (
      <div className="flex items-center gap-2">
        <Badge variant="outline">
          {partCount} av {partCount} delfakturor skapade
        </Badge>
        <Button size="sm" variant="ghost" asChild>
          <a href="/#/invoices">
            <ExternalLink className="mr-2 h-3 w-3" />
            Fakturor
          </a>
        </Button>
      </div>
    );
  }

  if (!isInstallment && deal.fortnox_invoice_number) {
    return (
      <div className="flex items-center gap-2">
        <Badge variant="outline">Faktura · {deal.fortnox_invoice_number}</Badge>
        <Button size="sm" variant="ghost" asChild>
          <a href="/#/invoices">
            <ExternalLink className="mr-2 h-3 w-3" />
            Fakturor
          </a>
        </Button>
      </div>
    );
  }

  return (
    <>
      <Button
        size="sm"
        variant="outline"
        onClick={() => setConfirming(true)}
        disabled={isPending}
        title={
          isInstallment
            ? `Skapar ett fakturautkast i Fortnox på delbetalning ${partIndex} av ${partCount}`
            : "Skapar ett fakturautkast i Fortnox på affärens engångsbelopp"
        }
      >
        <FileText className="mr-2 h-4 w-4" />
        {isInstallment
          ? `Skapa delfaktura ${partIndex}/${partCount}`
          : "Skapa faktura i Fortnox"}
      </Button>

      <Dialog open={confirming} onOpenChange={setConfirming}>
        <DialogContent>
          <DialogHeader>
            <DialogTitle>
              {isInstallment
                ? `Fakturera del ${partIndex} av ${partCount} — ${formatCurrency(amountToInvoice)}?`
                : `Fakturera ${formatCurrency(amountToInvoice)}?`}
            </DialogTitle>
            <DialogDescription asChild>
              <div className="space-y-2 text-sm">
                <p>
                  En faktura på {formatCurrency(amountToInvoice)} ex moms skapas
                  i Fortnox för <strong>{deal.name}</strong>
                  {isInstallment
                    ? `, märkt som delbetalning ${partIndex}/${partCount} av totalt ${formatCurrency(total)}`
                    : ""}
                  . Saknas kunden i Fortnox läggs den upp automatiskt.
                </p>
                <p>
                  Fakturan blir ett <strong>utkast</strong> — den bokförs inte
                  och skickas inte till kunden förrän du gör det i Fortnox.
                </p>
                {isInstallment && partIndex < partCount ? (
                  <p className="text-muted-foreground">
                    Efter den här delen återstår {partCount - partIndex} av{" "}
                    {partCount}.
                  </p>
                ) : null}
              </div>
            </DialogDescription>
          </DialogHeader>
          <DialogFooter>
            <Button
              variant="ghost"
              onClick={() => setConfirming(false)}
              disabled={isPending}
            >
              Avbryt
            </Button>
            <Button onClick={() => mutate()} disabled={isPending}>
              {isPending
                ? "Skapar…"
                : isInstallment
                  ? "Skapa delfaktura"
                  : "Skapa faktura"}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </>
  );
};

import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import { Link2 } from "lucide-react";
import { useState } from "react";
import {
  useDataProvider,
  useNotify,
  useRecordContext,
  useRefresh,
} from "ra-core";

import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";

import type { CrmDataProvider } from "../providers/types";
import type { Company } from "../types";
import { formatCurrency } from "./invoiceFormat";

/**
 * Manual Fortnox linking for the customers the org-number match can't reach.
 *
 * Z-bud's fraktsedel invoices sit on a Fortnox customer with no matching org
 * number, so "Skapa i Fortnox" can't adopt it and "betalt" stays wrong. Here
 * the user pastes the exact customer number — or picks it straight from the
 * list of orphaned invoices — and the backend relinks the mirror on the spot.
 *
 * Only rendered while the company has no Fortnox link, so a linked customer
 * card stays clean.
 */
export const FortnoxLinkCard = () => {
  const company = useRecordContext<
    Company & { fortnox_customer_number?: string }
  >();
  const dataProvider = useDataProvider<CrmDataProvider>();
  const notify = useNotify();
  const refresh = useRefresh();
  const queryClient = useQueryClient();
  const [value, setValue] = useState("");

  const { data: unlinked } = useQuery({
    queryKey: ["fortnox", "unlinked-invoices"],
    queryFn: () => dataProvider.getUnlinkedFortnoxInvoices(),
    // Only worth loading when the user is actually looking at an unlinked card.
    enabled: !!company && !company.fortnox_customer_number,
  });

  const { mutate, isPending } = useMutation({
    mutationFn: (customerNumber: string) =>
      dataProvider.linkFortnoxCustomer(company!.id, customerNumber),
    onSuccess: (result) => {
      notify(
        result.relinked_invoices > 0
          ? `Kopplat till Fortnox-kundnr ${result.customer_number} — ${result.relinked_invoices} faktura(or) matchade`
          : `Kopplat till Fortnox-kundnr ${result.customer_number}`,
        { type: "info" },
      );
      queryClient.invalidateQueries({ queryKey: ["fortnox"] });
      queryClient.invalidateQueries({
        queryKey: ["customer-billing-overview"],
      });
      setValue("");
      refresh();
    },
    onError: (error: Error) =>
      notify(error.message || "Kunde inte koppla kundnumret", {
        type: "error",
      }),
  });

  if (!company || company.fortnox_customer_number) return null;

  const suggestions = unlinked ?? [];

  return (
    <div className="space-y-2 rounded-md border border-dashed p-3 text-sm">
      <h3 className="flex items-center gap-2 font-semibold">
        <Link2 className="h-4 w-4" />
        Koppla Fortnox-kund
      </h3>
      <p className="text-xs text-muted-foreground">
        Fakturor matchas på org.nr. Går det inte — klistra in kundnumret från
        Fortnox här, så kopplas betalningarna direkt.
      </p>

      <div className="flex items-center gap-2">
        <Input
          value={value}
          onChange={(e) => setValue(e.target.value)}
          placeholder="Kundnr, t.ex. 42"
          className="h-8"
          onKeyDown={(e) => {
            if (e.key === "Enter" && value.trim() && !isPending) {
              mutate(value.trim());
            }
          }}
        />
        <Button
          size="sm"
          variant="outline"
          disabled={!value.trim() || isPending}
          onClick={() => mutate(value.trim())}
        >
          Koppla
        </Button>
      </div>

      {suggestions.length > 0 ? (
        <div className="space-y-1 pt-1">
          <p className="text-xs font-medium text-muted-foreground">
            Omatchade fakturor i Fortnox
          </p>
          {suggestions.slice(0, 5).map((s) => (
            <button
              key={s.customer_number}
              type="button"
              disabled={isPending}
              onClick={() => mutate(s.customer_number)}
              className="flex w-full items-center justify-between gap-2 rounded px-1 py-1 text-left hover:bg-muted/50 disabled:opacity-50"
            >
              <span className="min-w-0 flex-1 truncate">
                <span className="text-muted-foreground">
                  #{s.customer_number}
                </span>{" "}
                {s.customer_name ?? "—"}
              </span>
              <span className="shrink-0 text-muted-foreground">
                {s.invoice_count} st · {formatCurrency(s.total_amount)}
              </span>
            </button>
          ))}
        </div>
      ) : null}
    </div>
  );
};

import { useMutation, useQueryClient } from "@tanstack/react-query";
import { Building2, Check } from "lucide-react";
import {
  useDataProvider,
  useNotify,
  useRecordContext,
  useRefresh,
} from "ra-core";

import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";

import type { CrmDataProvider } from "../providers/types";
import type { Company } from "../types";

/**
 * Pushes the company to Fortnox as a customer. Safe to click twice: the backend
 * matches on organisation number, so an existing Fortnox customer is adopted
 * rather than duplicated.
 */
export const FortnoxCustomerButton = () => {
  const company = useRecordContext<
    Company & { fortnox_customer_number?: string }
  >();
  const dataProvider = useDataProvider<CrmDataProvider>();
  const notify = useNotify();
  const refresh = useRefresh();
  const queryClient = useQueryClient();

  const { mutate, isPending } = useMutation({
    mutationFn: () => dataProvider.syncCompanyToFortnox(company!.id),
    onSuccess: ({ customer_number, action }) => {
      const what =
        action === "created"
          ? "skapades i Fortnox"
          : action === "linked"
            ? "fanns redan i Fortnox och kopplades"
            : "uppdaterades i Fortnox";
      notify(`Kunden ${what} (kundnr ${customer_number})`, { type: "info" });
      queryClient.invalidateQueries({ queryKey: ["fortnox"] });
      refresh();
    },
    // The backend explains exactly what is missing (e.g. org_number), so show
    // that rather than a generic failure.
    onError: (error: Error) =>
      notify(error.message || "Kunde inte skapa kunden i Fortnox", {
        type: "error",
      }),
  });

  if (!company) return null;

  return (
    <div className="flex items-center gap-2">
      <Button
        size="sm"
        variant="outline"
        onClick={() => mutate()}
        disabled={isPending}
      >
        <Building2 className="mr-2 h-4 w-4" />
        {company.fortnox_customer_number
          ? "Uppdatera i Fortnox"
          : "Skapa i Fortnox"}
      </Button>
      {company.fortnox_customer_number ? (
        <Badge variant="outline" className="gap-1">
          <Check className="h-3 w-3" />
          Fortnox {company.fortnox_customer_number}
        </Badge>
      ) : null}
    </div>
  );
};

import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import {
  AlertTriangle,
  BellRing,
  CalendarClock,
  RefreshCw,
  TrendingDown,
  TrendingUp,
  Wallet,
  X,
} from "lucide-react";
import { useDataProvider, useNotify } from "ra-core";
import { useMemo, useState } from "react";

import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Card, CardContent } from "@/components/ui/card";
import { Skeleton } from "@/components/ui/skeleton";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";

import type { CrmDataProvider } from "../providers/types";
import type { FortnoxNamedSubscription } from "../types";
import { classifyRecurring, estimatedMonthlyCost } from "./economyFormat";
import { formatCurrency, formatDate } from "./invoiceFormat";

const StatCard = ({
  label,
  value,
  sub,
  tone,
  icon: Icon,
}: {
  label: string;
  value: string;
  sub?: string;
  tone?: "danger" | "positive";
  icon: React.ElementType;
}) => (
  <Card>
    <CardContent className="pt-6">
      <div className="flex items-center justify-between">
        <span className="text-sm text-muted-foreground">{label}</span>
        <Icon
          className={
            tone === "danger"
              ? "h-4 w-4 text-destructive"
              : tone === "positive"
                ? "h-4 w-4 text-emerald-600"
                : "h-4 w-4 text-muted-foreground"
          }
        />
      </div>
      <div
        className={`mt-2 text-2xl font-semibold ${
          tone === "danger"
            ? "text-destructive"
            : tone === "positive"
              ? "text-emerald-600"
              : ""
        }`}
      >
        {value}
      </div>
      {sub ? (
        <div className="mt-1 text-xs text-muted-foreground">{sub}</div>
      ) : null}
    </CardContent>
  </Card>
);

/** A named subscription enriched with its classification + monthly cost. */
type Subscription = FortnoxNamedSubscription & {
  kind: ReturnType<typeof classifyRecurring>;
  monthlyCost: number;
};

export const EconomyPage = () => {
  const dataProvider = useDataProvider<CrmDataProvider>();
  const notify = useNotify();
  const queryClient = useQueryClient();
  const thisYear = new Date().getFullYear().toString();
  const [bannerDismissed, setBannerDismissed] = useState(false);

  const { data: result, isPending: resultPending } = useQuery({
    queryKey: ["fortnox", "result-monthly"],
    queryFn: () => dataProvider.getFortnoxResultMonthly(),
  });

  const { data: subscriptionsRaw } = useQuery({
    queryKey: ["fortnox", "named-subscriptions"],
    queryFn: () => dataProvider.getFortnoxNamedSubscriptions(),
  });

  const { data: byAccount } = useQuery({
    queryKey: ["fortnox", "cost-by-account"],
    queryFn: () => dataProvider.getFortnoxCostByAccount(),
  });

  const { data: supplierInvoices } = useQuery({
    queryKey: ["fortnox", "supplier-invoices"],
    queryFn: () => dataProvider.getFortnoxSupplierInvoices(),
  });

  const { mutate: sync, isPending: isSyncing } = useMutation({
    mutationFn: () => dataProvider.syncFortnoxVouchers(),
    onSuccess: ({ synced, remaining }) => {
      notify(
        remaining > 0
          ? `Synkade ${synced} verifikationer — ${remaining} kvar, kör igen`
          : `Synkade ${synced} verifikationer från Fortnox`,
        { type: "info" },
      );
      queryClient.invalidateQueries({ queryKey: ["fortnox"] });
    },
    onError: () => notify("Kunde inte synka från Fortnox", { type: "error" }),
  });

  // Year-to-date totals from the result report. All figures come straight from
  // the bookkeeping, so revenue − cost reconciles to Fortnox's own result.
  const totals = useMemo(() => {
    const rows = (result ?? []).filter((r) => r.month.startsWith(thisYear));
    return rows.reduce(
      (acc, r) => ({
        revenue: acc.revenue + r.revenue,
        cost: acc.cost + r.cost,
        result: acc.result + r.result,
      }),
      { revenue: 0, cost: 0, result: 0 },
    );
  }, [result, thisYear]);

  const subscriptions = useMemo<Subscription[]>(
    () =>
      (subscriptionsRaw ?? [])
        .map((s) => ({
          ...s,
          kind: classifyRecurring(s),
          monthlyCost: estimatedMonthlyCost(s),
        }))
        .sort((a, b) => b.monthlyCost - a.monthlyCost),
    [subscriptionsRaw],
  );

  const fixedSubscriptions = subscriptions.filter(
    (s) => s.kind === "subscription",
  );
  const subscriptionMonthlyTotal = fixedSubscriptions.reduce(
    (sum, s) => sum + s.monthlyCost,
    0,
  );

  // Newly-recurring costs: a subscription whose first charge landed in the last
  // ~45 days. The bank (Lunar) flags a brand-new charge; this catches the
  // moment it turns into a recurring commitment — the point to check it's
  // intended. Complements, doesn't duplicate, the bank alert.
  const newlyRecurring = useMemo(() => {
    const cutoff = new Date();
    cutoff.setDate(cutoff.getDate() - 45);
    const cutoffIso = cutoff.toISOString().slice(0, 10);
    return (subscriptionsRaw ?? []).filter(
      (s) => s.first_invoice_date != null && s.first_invoice_date >= cutoffIso,
    );
  }, [subscriptionsRaw]);

  const unpaidSupplier = useMemo(() => {
    const rows = (supplierInvoices ?? []).filter(
      (r) => r.status === "unpaid" || r.status === "overdue",
    );
    const balance = rows.reduce((sum, r) => sum + (r.balance ?? 0), 0);
    const overdue = rows.filter((r) => r.status === "overdue").length;
    return { rows, balance, overdue };
  }, [supplierInvoices]);

  return (
    <div className="space-y-6" data-tour="economy-page">
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-semibold">Ekonomi</h1>
          <p className="text-sm text-muted-foreground">
            Speglat ur Fortnox bokföring — samma siffror som resultatrapporten
          </p>
        </div>
        <Button variant="outline" onClick={() => sync()} disabled={isSyncing}>
          <RefreshCw
            className={`mr-2 h-4 w-4 ${isSyncing ? "animate-spin" : ""}`}
          />
          Synka nu
        </Button>
      </div>

      {newlyRecurring.length > 0 && !bannerDismissed ? (
        <div className="flex items-start gap-3 rounded-lg border border-amber-300 bg-amber-50 p-4 text-amber-900 dark:border-amber-800 dark:bg-amber-950/40 dark:text-amber-200">
          <BellRing className="mt-0.5 h-5 w-5 shrink-0" />
          <div className="flex-1 text-sm">
            <p className="font-medium">
              {newlyRecurring.length === 1
                ? "Ny återkommande kostnad upptäckt"
                : `${newlyRecurring.length} nya återkommande kostnader upptäckta`}
            </p>
            <p className="mt-0.5">
              {newlyRecurring
                .map((s) => s.name ?? s.normalized_name)
                .join(", ")}{" "}
              — kontrollera att abonnemanget är avsett.
            </p>
          </div>
          <button
            type="button"
            onClick={() => setBannerDismissed(true)}
            className="rounded p-1 hover:bg-amber-100 dark:hover:bg-amber-900/40"
            aria-label="Stäng"
          >
            <X className="h-4 w-4" />
          </button>
        </div>
      ) : null}

      <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-4">
        <StatCard
          label={`Resultat ${thisYear}`}
          value={formatCurrency(totals.result)}
          sub="intäkter − kostnader, ur bokföringen"
          tone={totals.result >= 0 ? "positive" : "danger"}
          icon={totals.result >= 0 ? TrendingUp : TrendingDown}
        />
        <StatCard
          label={`Intäkter ${thisYear}`}
          value={formatCurrency(totals.revenue)}
          icon={TrendingUp}
        />
        <StatCard
          label={`Kostnader ${thisYear}`}
          value={formatCurrency(totals.cost)}
          icon={Wallet}
        />
        <StatCard
          label="Abonnemang"
          value={`${formatCurrency(subscriptionMonthlyTotal)}/mån`}
          sub={`${fixedSubscriptions.length} med fast belopp`}
          icon={CalendarClock}
        />
      </div>

      {subscriptions.length > 0 ? (
        <Card>
          <CardContent className="p-0">
            <div className="p-4 pb-0">
              <h2 className="font-semibold">Abonnemang &amp; återkommande</h2>
              <p className="text-sm text-muted-foreground">
                Avlästa direkt ur bokföringen och namngivna per leverantör.
                Fasta belopp är abonnemang; rörliga varierar mellan månaderna.
              </p>
            </div>
            <Table>
              <TableHeader>
                <TableRow>
                  <TableHead>Leverantör</TableHead>
                  <TableHead className="text-right">Per månad</TableHead>
                  <TableHead>Typ</TableHead>
                  <TableHead className="text-right">Antal</TableHead>
                  <TableHead>Senast</TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {subscriptions.map((s) => (
                  <TableRow key={s.normalized_name}>
                    <TableCell className="font-medium">
                      {s.name ?? s.normalized_name}
                    </TableCell>
                    <TableCell className="text-right">
                      {formatCurrency(s.monthlyCost)}
                    </TableCell>
                    <TableCell>
                      <Badge
                        variant={
                          s.kind === "subscription" ? "secondary" : "outline"
                        }
                      >
                        {s.kind === "subscription" ? "Abonnemang" : "Rörligt"}
                      </Badge>
                    </TableCell>
                    <TableCell className="text-right">
                      {s.invoice_count}
                    </TableCell>
                    <TableCell>{formatDate(s.last_invoice_date)}</TableCell>
                  </TableRow>
                ))}
              </TableBody>
            </Table>
          </CardContent>
        </Card>
      ) : null}

      <div className="grid gap-6 lg:grid-cols-2">
        <Card>
          <CardContent className="p-0">
            <div className="p-4 pb-0">
              <h2 className="font-semibold">Resultat per månad</h2>
            </div>
            {resultPending ? (
              <div className="space-y-2 p-6">
                <Skeleton className="h-8 w-full" />
                <Skeleton className="h-8 w-full" />
              </div>
            ) : (result ?? []).length === 0 ? (
              <p className="p-6 text-sm text-muted-foreground">
                Inga verifikationer speglade ännu. Klicka Synka nu.
              </p>
            ) : (
              <Table>
                <TableHeader>
                  <TableRow>
                    <TableHead>Månad</TableHead>
                    <TableHead className="text-right">Intäkter</TableHead>
                    <TableHead className="text-right">Kostnader</TableHead>
                    <TableHead className="text-right">Resultat</TableHead>
                  </TableRow>
                </TableHeader>
                <TableBody>
                  {[...(result ?? [])].reverse().map((m) => (
                    <TableRow key={m.month}>
                      <TableCell>{m.month.slice(0, 7)}</TableCell>
                      <TableCell className="text-right">
                        {formatCurrency(m.revenue)}
                      </TableCell>
                      <TableCell className="text-right">
                        {formatCurrency(m.cost)}
                      </TableCell>
                      <TableCell
                        className={`text-right font-medium ${
                          m.result < 0 ? "text-destructive" : ""
                        }`}
                      >
                        {formatCurrency(m.result)}
                      </TableCell>
                    </TableRow>
                  ))}
                </TableBody>
              </Table>
            )}
          </CardContent>
        </Card>

        <Card>
          <CardContent className="p-0">
            <div className="p-4 pb-0">
              <h2 className="font-semibold">Kostnad per konto</h2>
              <p className="text-sm text-muted-foreground">
                Vart pengarna tar vägen (BAS-konto).
              </p>
            </div>
