import { useNotify } from "ra-core";
import { useCallback, useEffect, useRef, useState } from "react";

import {
  imagesFromClipboard,
  type PendingFeedbackImage,
  pickFeedbackImages,
} from "./feedbackImageRules";

/**
 * Håller de bilder som valts men ännu inte laddats upp.
 *
 * Delas av input-baren och redigeringsformuläret så att gränserna, felnotiserna
 * och städningen av object-URL:er är identiska. Previews revokas både när en
 * bild tas bort och när komponenten avmonteras — Radix avmonterar
 * PopoverContent varje gång widgeten stängs, så utan det läcker varje
 * öppna/stäng-cykel.
 */
export const usePendingFeedbackImages = () => {
  const notify = useNotify();
  const [pending, setPending] = useState<PendingFeedbackImage[]>([]);

  const previewsRef = useRef<string[]>([]);
  useEffect(() => {
    previewsRef.current = pending.map((image) => image.preview);
  }, [pending]);
  useEffect(
    () => () => previewsRef.current.forEach((url) => URL.revokeObjectURL(url)),
    [],
  );

  const addFiles = useCallback(
    (files: File[], room: number) => {
      const { accepted, errors } = pickFeedbackImages(files, room);
      errors.forEach((message) => notify(message, { type: "warning" }));
      if (accepted.length === 0) return;
      setPending((prev) => [
        ...prev,
        ...accepted.map((file) => ({
          file,
          preview: URL.createObjectURL(file),
        })),
      ]);
    },
    [notify],
  );

  /** Ctrl+V av en skärmdump. Returnerar true när eventet konsumerats. */
  const addFromClipboard = useCallback(
    (data: DataTransfer | null, room: number) => {
      const files = imagesFromClipboard(data);
      if (files.length === 0) return false;
      addFiles(files, room);
      return true;
    },
    [addFiles],
  );

  const removeAt = useCallback((index: number) => {
    setPending((prev) => {
      const target = prev[index];
      if (target) URL.revokeObjectURL(target.preview);
      return prev.filter((_, position) => position !== index);
    });
  }, []);

  const clear = useCallback(() => {
    setPending((prev) => {
      prev.forEach((image) => URL.revokeObjectURL(image.preview));
      return [];
    });
  }, []);

  return { pending, addFiles, addFromClipboard, removeAt, clear };
};

import { useGetList } from "ra-core";

import type { FeedbackItem, FeedbackStatus } from "../types";

/**
 * Hämtar feedback-tråden för den delade inkorgen.
 *
 * - Sorterar ASC på created_at så nyaste hamnar nederst (chatt-ordning).
 * - Pollar var 15:e sekund när panelen är öppen så att teamets poster
 *   dyker upp live; polling pausas helt när panelen är stängd.
 * - pollingPaused stänger av pollingen under redigering, så listan inte byts
 *   ut mitt i ett utkast. Cachen behålls (enabled styrs bara av `open`).
 */
export const useGetFeedback = (
  open: boolean,
  statusFilter?: FeedbackStatus,
  pollingPaused = false,
) =>
  useGetList<FeedbackItem>(
    "feedback_items",
    {
      sort: { field: "created_at", order: "ASC" },
      pagination: { page: 1, perPage: 200 },
      filter: statusFilter ? { status: statusFilter } : {},
    },
    {
      enabled: open,
      refetchInterval: open && !pollingPaused ? 15000 : false,
      refetchOnWindowFocus: !pollingPaused,
    },
  );

import { supabase } from "../providers/supabase/supabase";
import {
  FEEDBACK_IMAGES_BUCKET,
  feedbackImagePath,
} from "./feedbackImageRules";

/**
 * Storage-anropen för bildbilagor i feedback-widgeten.
 *
 * Egen modul i stället för dataProviderns beforeSave-mönster (som notes använder):
 * här finns inga RAFile från ett ra-formulär utan råa File från en <input>, felen
 * ska visas på svenska i widgeten, och redigeringen kräver en ordning som
 * lifecycle-callbacks inte kan uttrycka (ladda upp → skriv raden → städa först
 * därefter de bilder som länkats bort).
 *
 * Gränserna och de rena hjälpfunktionerna bor i feedbackImageRules.ts och
 * återexporteras här, så komponenter bara behöver importera den här modulen.
 */
export * from "./feedbackImageRules";

/**
 * auth.uid() (uuid) — bucketpolicyn kräver att första mappnivån är den.
 * OBS: useGetIdentity().id är sales.id (bigint) och skulle ge 403 här.
 */
const getAuthUserId = async (): Promise<string | null> => {
  const { data } = await supabase.auth.getSession();
  return data.session?.user.id ?? null;
};

/** Best effort-radering. Kastar aldrig — används i städ-/felvägar. */
const removePaths = async (paths: string[]): Promise<void> => {
  if (paths.length === 0) return;
  const { error } = await supabase.storage
    .from(FEEDBACK_IMAGES_BUCKET)
    .remove(paths);
  if (error) {
    console.error("removeFeedbackImages:", error);
  }
};

/**
 * Laddar upp sekventiellt och returnerar publika URL:er i samma ordning.
 *
 * Allt-eller-inget: misslyckas en fil mitt i batchen städas de som redan
 * hunnit upp innan felet kastas vidare, så bucketen aldrig får filer som
 * ingen rad pekar på. Anroparen ska avbryta hela sparningen — hellre det än
 * ett meddelande utan den skärmdump som förklarar felet.
 */
export const uploadFeedbackImages = async (
  files: File[],
): Promise<string[]> => {
  if (files.length === 0) return [];

  const userId = await getAuthUserId();
  if (!userId) {
    throw new Error("Du måste vara inloggad för att bifoga bilder");
  }

  const uploadedPaths: string[] = [];
  try {
    const urls: string[] = [];
    for (const file of files) {
      const ext = file.name.split(".").pop()?.toLowerCase() || "png";
      // Egen mapp per användare — uppladdningspolicyn kräver det.
      const path = `${userId}/${crypto.randomUUID()}.${ext}`;
      const { error } = await supabase.storage
        .from(FEEDBACK_IMAGES_BUCKET)
        .upload(path, file, { contentType: file.type });

      if (error) {
        console.error("uploadFeedbackImages:", error);
        throw new Error(`Kunde inte ladda upp ${file.name}. Försök igen.`);
      }

      uploadedPaths.push(path);
      urls.push(
        supabase.storage.from(FEEDBACK_IMAGES_BUCKET).getPublicUrl(path).data
          .publicUrl,
      );
    }
    return urls;
  } catch (error) {
    await removePaths(uploadedPaths);
    throw error;
  }
};

/**
 * Best effort-städning av filer som ingen rad längre pekar på.
 * Kastar inte: raden är redan skriven, och ett misslyckat storage-anrop ska
 * inte få det att se ut som att sparningen gick fel.
 */
export const deleteFeedbackImages = async (urls: string[]): Promise<void> => {
  await removePaths(
    urls
      .map((url) => feedbackImagePath(url))
      .filter((path): path is string => path != null),
  );
};

/**
 * Rena regler för bildbilagor i feedback-widgeten — gränser, filtrering och
 * URL-tolkning. Egen fil utan supabase-import så reglerna kan enhetstestas
 * (vitest kör i browser-mode utan .env, där en import av supabase-klienten kastar).
 * Storage-anropen ligger i feedbackImages.ts, som återexporterar allt härifrån.
 */

export const FEEDBACK_IMAGES_BUCKET = "feedback-images";
export const MAX_FEEDBACK_IMAGES = 3;
/** Speglar bucketens file_size_limit i 20260817120000_feedback_images_and_edit.sql. */
export const MAX_FEEDBACK_IMAGE_BYTES = 5 * 1024 * 1024;
/**
 * Speglar bucketens allowed_mime_types EXAKT. Vi filtrerar på samma lista här,
 * inte bara på "image/*": annars accepterar klienten t.ex. SVG som bucketen
 * sedan avvisar, mitt i en batch där tidigare bilder redan laddats upp.
 * HEIC är medvetet utelämnat — Chrome/Firefox renderar det inte i <img>, så
 * tumnageln hade blivit trasig. (iOS konverterar normalt till JPEG vid uppladdning.)
 */
export const FEEDBACK_IMAGE_MIME_TYPES = [
  "image/png",
  "image/jpeg",
  "image/webp",
  "image/gif",
] as const;

export type PendingFeedbackImage = { file: File; preview: string };

/** accept-attributet för filväljaren, så dialogen inte ens erbjuder fel format. */
export const FEEDBACK_IMAGE_ACCEPT = FEEDBACK_IMAGE_MIME_TYPES.join(",");

const isAllowedFeedbackImage = (file: File) =>
  (FEEDBACK_IMAGE_MIME_TYPES as readonly string[]).includes(file.type);

/**
 * Filtrerar valda filer mot antal-, typ- och storleksgränserna.
 * Ren funktion utan sidoeffekter, så filväljaren och inklistringen
 * använder exakt samma regler.
 */
export const pickFeedbackImages = (
  files: File[],
  room: number,
): { accepted: File[]; errors: string[] } => {
  const errors: string[] = [];

  const images = files.filter((file) => {
    if (isAllowedFeedbackImage(file)) return true;
    errors.push(
      file.type.startsWith("image/")
        ? `${file.name} har ett bildformat som inte stöds (använd PNG, JPG, WEBP eller GIF).`
        : `${file.name} är inte en bild.`,
    );
    return false;
  });

  if (images.length > Math.max(0, room)) {
    errors.push(`Max ${MAX_FEEDBACK_IMAGES} bilder per meddelande.`);
  }

  const accepted = images.slice(0, Math.max(0, room)).filter((file) => {
    if (file.size <= MAX_FEEDBACK_IMAGE_BYTES) return true;
    errors.push(`${file.name} är större än 5 MB och hoppades över.`);
    return false;
  });

  return { accepted, errors };
};

/**
 * Plockar bildfiler ur ett paste-event, så en skärmdump kan klistras in
 * direkt i textfältet med Ctrl+V.
 */
export const imagesFromClipboard = (data: DataTransfer | null): File[] => {
  if (!data) return [];
  return Array.from(data.items)
    .filter((item) => item.kind === "file" && item.type.startsWith("image/"))
    .map((item) => item.getAsFile())
    .filter((file): file is File => file != null);
};

/** Publik URL → storage-path, eller null om URL:en inte hör till bucketen. */
export const feedbackImagePath = (url: string): string | null => {
  const marker = `/${FEEDBACK_IMAGES_BUCKET}/`;
  const index = url.lastIndexOf(marker);
  if (index === -1) return null;
  const path = url.slice(index + marker.length);
  return path.length > 0 ? path : null;
};

