import {
  FEEDBACK_IMAGE_ACCEPT,
  MAX_FEEDBACK_IMAGES,
  deleteFeedbackImages,
  uploadFeedbackImages,
} from "./feedbackImages";
import { usePendingFeedbackImages } from "./usePendingFeedbackImages";

export const FeedbackInputBar = ({ onCreated }: { onCreated: () => void }) => {
  const [create, { isPending }] = useCreate();
  const notify = useNotify();
  const [text, setText] = useState("");
  const [category, setCategory] = useState<FeedbackCategory>("works");
  const [isUploading, setIsUploading] = useState(false);
  const images = usePendingFeedbackImages();
  const fileInputRef = useRef<HTMLInputElement>(null);

  const room = MAX_FEEDBACK_IMAGES - images.pending.length;
  const isBusy = isPending || isUploading;

  const handleSend = async () => {
    const trimmed = text.trim();
    if (!trimmed || isBusy) return;

    // Bilderna laddas upp FÖRE raden: misslyckas de sparas ingen feedback alls,
    // hellre än en buggrapport utan den skärmdump som förklarar felet.
    let imageUrls: string[] = [];
    if (images.pending.length > 0) {
      setIsUploading(true);
      try {
        imageUrls = await uploadFeedbackImages(
          images.pending.map((image) => image.file),
        );
      } catch (error) {
        notify(
          error instanceof Error
            ? error.message
            : "Kunde inte ladda upp bilderna",
          { type: "error" },
        );
        return;
      } finally {
        setIsUploading(false);
      }
    }

    create(
      "feedback_items",
      {
        // Skicka INTE sales_id — det fylls av DB-triggern (set_sales_id_default).
        data: {
          text: trimmed,
          category,
          status: "open",
          page_context: window.location.pathname,
          image_urls: imageUrls,
        },
      },
      {
        onSuccess: () => {
          setText("");
          images.clear();
          onCreated();
        },
        onError: () => {
          // Raden blev inte sparad → städa bilderna som redan hunnit upp, annars
          // ligger de kvar i bucketen utan att någon rad pekar på dem.
          void deleteFeedbackImages(imageUrls);
          notify("Kunde inte spara feedback", { type: "error" });
        },
      },
    );
  };

  const handleKeyDown = (event: React.KeyboardEvent<HTMLTextAreaElement>) => {
    // Enter skickar, Shift+Enter ger radbrytning.
    if (event.key === "Enter" && !event.shiftKey) {
      event.preventDefault();
      void handleSend();
    }
  };

  const handlePaste = (event: React.ClipboardEvent<HTMLTextAreaElement>) => {
    // Inklistrad skärmdump (Win+Shift+S → Ctrl+V) blir en bilaga i stället för text.
    if (images.addFromClipboard(event.clipboardData, room)) {
      event.preventDefault();
    }
  };

  return (
    <div className="border-t p-3">
      <FeedbackCategoryToggle
        value={category}
        onChange={setCategory}
        className="mb-2"
      />

      {images.pending.length > 0 && (
        <div className="mb-2">
          <FeedbackImagePicker
            pending={images.pending}
            onAdd={(files) => images.addFiles(files, room)}
            onRemovePending={images.removeAt}
            disabled={isBusy}
            showAddTile={false}
          />
        </div>
      )}

      <div className="flex items-end gap-2">
        <Textarea
          value={text}
          onChange={(event) => setText(event.target.value)}
          onKeyDown={handleKeyDown}
          onPaste={handlePaste}
          placeholder="Skriv feedback…"
          rows={2}
          // text-base på mobil: iOS Safari zoomar in på fält under 16px, vilket
          // skulle dra popovern halvt utanför skärmen när man börjar skriva.
          className="max-h-32 min-h-9 min-w-0 flex-1 resize-none text-base sm:text-sm"
        />

        {/* Egen knapp utanför FeedbackImagePicker, så första bilagan är nåbar
            innan förhandsvisningsraden ens finns. */}
        {room > 0 && (
          <TooltipProvider>
            <Tooltip>
              <TooltipTrigger asChild>
                <Button
                  variant="ghost"
                  size="sm"
                  onClick={() => fileInputRef.current?.click()}
                  disabled={isBusy}
                  aria-label="Bifoga bild"
                  className="h-10 w-10 shrink-0 cursor-pointer p-0"
                >
                  <ImagePlus className="h-4 w-4" />
                </Button>
              </TooltipTrigger>
              <TooltipContent>
                Bifoga bild (eller klistra in med Ctrl+V)
              </TooltipContent>
            </Tooltip>
          </TooltipProvider>
        )}
        <input
          ref={fileInputRef}
          type="file"
          accept={FEEDBACK_IMAGE_ACCEPT}
          multiple
          className="hidden"
          onChange={(event) => {
            images.addFiles(Array.from(event.target.files ?? []), room);
            event.target.value = "";
          }}
        />

        <Button
          onClick={() => void handleSend()}
          disabled={isBusy || !text.trim()}
          size="sm"
          aria-label="Skicka feedback"
          className="h-10 w-10 shrink-0 cursor-pointer p-0"
        >
          <SendHorizonal className="h-4 w-4" />
        </Button>
      </div>
    </div>
  );
};

import { ImagePlus, X } from "lucide-react";
import { useRef } from "react";

import { cn } from "@/lib/utils";

import {
  FEEDBACK_IMAGE_ACCEPT,
  MAX_FEEDBACK_IMAGES,
  type PendingFeedbackImage,
} from "./feedbackImageRules";

/**
 * Bild-UI:t för feedback-widgeten: förhandsvisningar + "lägg till bild"-tile.
 *
 * Delas av input-baren och redigeringsformuläret. Den hanterar två separata
 * listor — redan sparade URL:er (`existingUrls`) och nya, ännu inte uppladdade
 * filer (`pending`) — vilket är det som gör "ta bort en gammal bild" och
 * "lägg till en ny" komponerbart i samma formulär.
 *
 * X-knapparna hålls visuellt små (20px) för att inte täcka tumnageln, men får
 * en osynlig `before:`-yta på ~36px så de går att träffa med ett finger.
 */
export const FeedbackImagePicker = ({
  existingUrls = [],
  pending,
  onAdd,
  onRemoveExisting,
  onRemovePending,
  thumbClassName = "h-14 w-14",
  disabled = false,
  showAddTile = true,
}: {
  existingUrls?: string[];
  pending: PendingFeedbackImage[];
  onAdd: (files: File[]) => void;
  onRemoveExisting?: (url: string) => void;
  onRemovePending: (index: number) => void;
  thumbClassName?: string;
  disabled?: boolean;
  /** Av i input-baren, som har en egen kompakt bifoga-knapp vid skicka-knappen. */
  showAddTile?: boolean;
}) => {
  const inputRef = useRef<HTMLInputElement>(null);
  const room = MAX_FEEDBACK_IMAGES - existingUrls.length - pending.length;

  return (
    <div className="flex flex-wrap items-center gap-1.5">
      <input
        ref={inputRef}
        type="file"
        accept={FEEDBACK_IMAGE_ACCEPT}
        multiple
        className="hidden"
        onChange={(event) => {
          onAdd(Array.from(event.target.files ?? []));
          // Nollställ så samma fil kan väljas igen efter att den tagits bort.
          event.target.value = "";
        }}
      />

      {existingUrls.map((url) => (
        <div key={url} className="relative">
          <img
            src={url}
            alt="Skärmdump"
            loading="lazy"
            className={cn("rounded-md border object-cover", thumbClassName)}
          />
          {onRemoveExisting && (
            <button
              type="button"
              onClick={() => onRemoveExisting(url)}
              disabled={disabled}
              aria-label="Ta bort bilden"
              className="absolute -top-1.5 -right-1.5 flex h-5 w-5 cursor-pointer items-center justify-center rounded-full bg-destructive text-destructive-foreground before:absolute before:-inset-2"
            >
              <X className="h-3 w-3" />
            </button>
          )}
        </div>
      ))}

      {pending.map((image, index) => (
        <div key={image.preview} className="relative">
          <img
            src={image.preview}
            alt={image.file.name}
            className={cn("rounded-md border object-cover", thumbClassName)}
          />
          <button
            type="button"
            onClick={() => onRemovePending(index)}
            disabled={disabled}
            aria-label="Ta bort bilden"
            className="absolute -top-1.5 -right-1.5 flex h-5 w-5 cursor-pointer items-center justify-center rounded-full bg-destructive text-destructive-foreground before:absolute before:-inset-2"
          >
            <X className="h-3 w-3" />
          </button>
        </div>
      ))}

      {showAddTile && room > 0 && (
        <button
          type="button"
          onClick={() => inputRef.current?.click()}
          disabled={disabled}
          aria-label="Lägg till bild"
          className={cn(
            "flex cursor-pointer flex-col items-center justify-center gap-0.5 rounded-md border border-dashed text-muted-foreground transition-colors hover:border-primary hover:text-primary",
            thumbClassName,
          )}
        >
          <ImagePlus className="h-4 w-4" />
          <span className="text-[10px]">Bild</span>
        </button>
      )}
    </div>
  );
};

import { useNotify, useUpdate } from "ra-core";
import { useState } from "react";

import { Button } from "@/components/ui/button";
import { Spinner } from "@/components/ui/spinner";
import { Textarea } from "@/components/ui/textarea";

import type { FeedbackCategory, FeedbackItem } from "../types";
import { FeedbackCategoryToggle } from "./FeedbackCategoryToggle";
import { FeedbackImagePicker } from "./FeedbackImagePicker";
import {
  MAX_FEEDBACK_IMAGES,
  deleteFeedbackImages,
  uploadFeedbackImages,
} from "./feedbackImages";
import { usePendingFeedbackImages } from "./usePendingFeedbackImages";

/**
 * Inline-redigering av ett skickat meddelande. Ersätter bubblan i tråden i
 * stället för att öppna en dialog — panelen är 24rem bred och en nästlad
 * Radix-dialog inuti popovern är onödigt bräcklig.
 *
 * Delad inkorg: alla i teamet får redigera allas meddelanden. DB-triggern
 * stämplar edited_at + edited_by_sales_id så ändringen alltid har ett spår.
 */
export const FeedbackEditForm = ({
  item,
  onCancel,
  onSaved,
}: {
  item: FeedbackItem;
  onCancel: () => void;
  onSaved: () => void;
}) => {
  const notify = useNotify();
  const [update] = useUpdate();
  const [text, setText] = useState(item.text);
  const [category, setCategory] = useState<FeedbackCategory>(item.category);
  const [existingUrls, setExistingUrls] = useState<string[]>(
    item.image_urls ?? [],
  );
  const [isSaving, setIsSaving] = useState(false);
  const images = usePendingFeedbackImages();

  const room =
    MAX_FEEDBACK_IMAGES - existingUrls.length - images.pending.length;

  const handleCancel = () => {
    images.clear();
    onCancel();
  };

  const handleSave = async () => {
    const trimmed = text.trim();
    if (!trimmed || isSaving) return;

    setIsSaving(true);
    let uploaded: string[] = [];
    try {
      uploaded = await uploadFeedbackImages(
        images.pending.map((image) => image.file),
      );
      const imageUrls = [...existingUrls, ...uploaded];

      await update(
        "feedback_items",
        {
          id: item.id,
          data: { text: trimmed, category, image_urls: imageUrls },
          // Obligatoriskt: postgrest-providern diffar mot previousData.
          previousData: item,
        },
        { returnPromise: true },
      );

      // Städa bort avlänkade filer FÖRST efter lyckad skrivning, annars kan
      // raden peka på bilder som redan är raderade.
      await deleteFeedbackImages(
        (item.image_urls ?? []).filter((url) => !imageUrls.includes(url)),
      );
      images.clear();
      onSaved();
    } catch (error) {
      // Raden blev inte sparad → de nyss uppladdade filerna är föräldralösa.
      await deleteFeedbackImages(uploaded);
      notify(
        error instanceof Error ? error.message : "Kunde inte spara ändringen",
        { type: "error" },
      );
    } finally {
      setIsSaving(false);
    }
  };

  return (
    <div className="space-y-2 rounded-lg border border-primary/40 bg-primary/5 p-3">
      <FeedbackCategoryToggle value={category} onChange={setCategory} />

      <Textarea
        value={text}
        onChange={(event) => setText(event.target.value)}
        onPaste={(event) => {
          if (images.addFromClipboard(event.clipboardData, room)) {
            event.preventDefault();
          }
        }}
        autoFocus
        rows={3}
        // text-base på mobil: iOS Safari zoomar in på fält under 16px.
        className="max-h-40 resize-none text-base sm:text-sm"
      />

      <FeedbackImagePicker
        existingUrls={existingUrls}
        pending={images.pending}
        onAdd={(files) => images.addFiles(files, room)}
        onRemoveExisting={(url) =>
          setExistingUrls((prev) => prev.filter((current) => current !== url))
        }
        onRemovePending={images.removeAt}
        thumbClassName="h-12 w-12"
        disabled={isSaving}
      />

      <div className="flex items-center justify-end gap-2">
        <Button
          variant="ghost"
          size="sm"
          onClick={handleCancel}
          disabled={isSaving}
          className="h-8 cursor-pointer px-3 text-xs"
        >
          Avbryt
        </Button>
        <Button
          size="sm"
          onClick={() => void handleSave()}
          disabled={isSaving || !text.trim()}
          className="h-8 cursor-pointer px-3 text-xs"
        >
          {isSaving ? <Spinner className="h-3 w-3" /> : "Spara"}
        </Button>
      </div>
    </div>
  );
};

import { ToggleGroup, ToggleGroupItem } from "@/components/ui/toggle-group";
import { cn } from "@/lib/utils";

import type { FeedbackCategory } from "../types";
import { FEEDBACK_CATEGORIES } from "./feedbackCategories";

/**
 * Kategoriväljaren. Delas av input-baren och redigeringsformuläret så att
 * "Funkar bra / Funkar inte / Förslag" ser och beter sig identiskt i båda.
 */
export const FeedbackCategoryToggle = ({
  value,
  onChange,
  className,
}: {
  value: FeedbackCategory;
  onChange: (value: FeedbackCategory) => void;
  className?: string;
}) => (
  <ToggleGroup
    type="single"
    value={value}
    onValueChange={(next) => next && onChange(next as FeedbackCategory)}
    variant="outline"
    // @container: etiketterna ska styras av den här radens bredd, inte
    // viewportens — panelen är alltid 24rem (eller mindre) även på en stor
    // skärm, så en sm:-breakpoint säger inget om utrymmet här.
    // w-full behövs: container-type gör att innehållet inte får bestämma bredden.
    className={cn("@container w-full", className)}
  >
    {FEEDBACK_CATEGORIES.map((option) => (
      <ToggleGroupItem
        key={option.value}
        value={option.value}
        // flex-auto ger innehållsbaserad basbredd (i stället för flex-1:s 0) och
        // rensar basvariantens shrink-0 via tailwind-merge, så knapparna krymper
        // i stället för att spränga panelen. Knapparna fyller raden ändå, så den
        // låga px-1 påverkar bara var etiketterna får plats — inte hur det ser ut.
        className="h-8 flex-auto gap-1 px-1 text-[11px]"
        aria-label={option.label}
        title={option.label}
      >
        <span aria-hidden="true">{option.emoji}</span>
        {/* De tre etiketterna kräver ~326px tillsammans — visa dem bara när
            raden faktiskt är bred nog (24rem-panelen ger 358px), annars talar
            emoji + aria-label/title om vad knappen gör. truncate är sista
            skyddsnätet om ett emoji-typsnitt är bredare än väntat. */}
        <span className="hidden min-w-0 truncate @min-[22rem]:inline">
          {option.label}
        </span>
      </ToggleGroupItem>
    ))}
  </ToggleGroup>
);

import { Check, Pencil, Trash2 } from "lucide-react";
import { useDelete, useGetIdentity, useNotify, useUpdate } from "ra-core";
import { useState } from "react";

import { Button } from "@/components/ui/button";
import {
  Tooltip,
  TooltipContent,
  TooltipProvider,
  TooltipTrigger,
} from "@/components/ui/tooltip";
import { cn } from "@/lib/utils";

import { RelativeDate } from "../misc/RelativeDate";
import { useGetSalesName } from "../sales/useGetSalesName";
import type { FeedbackItem } from "../types";
import { FeedbackAuthor } from "./FeedbackAuthor";
import { getFeedbackCategory } from "./feedbackCategories";
import { deleteFeedbackImages } from "./feedbackImages";

export const FeedbackBubble = ({
  item,
  canDelete,
  isEditingElsewhere,
  onStartEdit,
  onDeleted,
}: {
  item: FeedbackItem;
  canDelete: boolean;
  /** Ett annat meddelande redigeras just nu — se kommentaren vid pennan. */
  isEditingElsewhere: boolean;
  onStartEdit: () => void;
  onDeleted: () => void;
}) => {
  const { identity } = useGetIdentity();
  const notify = useNotify();
  const isCurrentUser = item.sales_id === identity?.id;
  const category = getFeedbackCategory(item.category);
  const isDone = item.status === "done";
  const images = item.image_urls ?? [];
  const [confirmDelete, setConfirmDelete] = useState(false);

  const [update, { isPending }] = useUpdate();
  const [deleteFeedback, { isPending: isDeleting }] = useDelete();

  // Redigeringen är teamgemensam, men vem som skrev om det ska synas.
  const editedByCurrentUser = item.edited_by_sales_id === identity?.id;
  const editorName = useGetSalesName(item.edited_by_sales_id ?? undefined, {
    enabled: item.edited_by_sales_id != null && !editedByCurrentUser,
  });
  const editedSuffix = item.edited_at
    ? editedByCurrentUser
      ? " · redigerad av dig"
      : editorName
        ? ` · redigerad av ${editorName}`
        : " · redigerad"
    : "";

  const toggleDone = () => {
    update(
      "feedback_items",
      {
        id: item.id,
        data: { status: isDone ? "open" : "done" },
        previousData: item,
      },
      { mutationMode: "optimistic" },
    );
  };

  const handleDelete = () => {
    // Pessimistiskt läge i stället för repots vanliga "undoable": en ångrad
    // radering kan inte få tillbaka bilder som redan städats ur bucketen, och
    // undoable anropar onSuccess optimistiskt så det finns ingen säker hook.
    deleteFeedback(
      "feedback_items",
      { id: item.id, previousData: item },
      {
        onSuccess: async () => {
          await deleteFeedbackImages(images);
          onDeleted();
        },
        onError: () => {
          setConfirmDelete(false);
          notify("Kunde inte radera meddelandet", { type: "error" });
        },
      },
    );
  };

  return (
    <div
      className={cn(
        "rounded-lg border p-3 text-sm transition-opacity",
        isDone && "opacity-60",
      )}
    >
      <div className="mb-1.5 flex items-center justify-between gap-2">
        <FeedbackAuthor salesId={item.sales_id} isCurrentUser={isCurrentUser} />
        <span className="min-w-0 text-right text-xs text-muted-foreground">
          <RelativeDate date={item.created_at} />
          {editedSuffix}
        </span>
      </div>

      <div className="flex items-start gap-2">
        {category && (
          <span
            className={cn(
              "mt-0.5 shrink-0 rounded px-1.5 py-0.5 text-xs",
              category.badgeClassName,
            )}
            title={category.label}
          >
            {category.emoji}
          </span>
        )}
        {/* min-w-0: utan den blir textens min-content-bredd (en lång URL eller
            ett långt ord) golvet för flexboxen och knuffar ut knappraden, vilket
            ger horisontell scroll i tråden. */}
        <p
          className={cn(
            "min-w-0 flex-1 whitespace-pre-wrap break-words",
            isDone && "line-through",
          )}
        >
          {item.text}
        </p>
        <TooltipProvider>
          <div className="flex shrink-0 items-center gap-1">
            <Tooltip>
              <TooltipTrigger asChild>
                {/* Låst medan ett annat meddelande redigeras: bara ett
                    formulär åt gången, och ett byte hade kastat de osparade
                    ändringarna (inklusive valda bilder) utan varning. */}
                <Button
                  variant="ghost"
                  size="sm"
                  onClick={onStartEdit}
                  disabled={isEditingElsewhere}
                  aria-label="Redigera"
                  className="h-8 w-8 cursor-pointer p-0"
                >
                  <Pencil className="h-3.5 w-3.5" />
                </Button>
              </TooltipTrigger>
              <TooltipContent>
                {isEditingElsewhere
                  ? "Spara eller avbryt den pågående redigeringen först"
                  : "Redigera"}
              </TooltipContent>
            </Tooltip>

            <Tooltip>
              <TooltipTrigger asChild>
                <Button
                  variant={isDone ? "secondary" : "ghost"}
                  size="sm"
                  onClick={toggleDone}
                  disabled={isPending}
                  aria-label={isDone ? "Markera som öppen" : "Markera som klar"}
                  className="h-8 w-8 cursor-pointer p-0"
                >
                  <Check className="h-4 w-4" />
                </Button>
              </TooltipTrigger>
              <TooltipContent>
                {isDone ? "Markera som öppen" : "Markera som klar"}
              </TooltipContent>
            </Tooltip>

            {canDelete && (
              <Tooltip>
                <TooltipTrigger asChild>
                  <Button
                    variant="ghost"
                    size="sm"
                    onClick={() => setConfirmDelete(true)}
                    disabled={isDeleting}
                    aria-label="Radera"
                    className="h-8 w-8 cursor-pointer p-0 text-muted-foreground hover:text-destructive"
                  >
                    <Trash2 className="h-3.5 w-3.5" />
                  </Button>
                </TooltipTrigger>
                <TooltipContent>Radera</TooltipContent>
              </Tooltip>
            )}
          </div>
        </TooltipProvider>
      </div>

      {images.length > 0 && (
        <div className="mt-2 flex flex-wrap gap-1.5">
          {images.map((url) => (
            /* Öppnas i ny flik i full storlek — panelen är för trång för att
               zooma i en skärmdump. */
            <a key={url} href={url} target="_blank" rel="noopener noreferrer">
              <img
                src={url}
                alt="Skärmdump"
                loading="lazy"
                className="h-16 w-16 rounded-md border object-cover transition-opacity hover:opacity-80"
              />
            </a>
          ))}
        </div>
      )}

      {/* flex-wrap: på en 288px-panel får text + två knappar inte plats på en
          rad — då lägger sig knapparna på egen rad i stället för att klämmas. */}
      {confirmDelete && (
        <div className="mt-2 flex flex-wrap items-center justify-between gap-2 rounded-md border border-destructive/40 bg-destructive/5 p-2">
          <span className="text-xs">Radera meddelandet?</span>
          <div className="ml-auto flex items-center gap-2">
            <Button
              variant="ghost"
              size="sm"
              onClick={() => setConfirmDelete(false)}
              disabled={isDeleting}
              className="h-8 cursor-pointer px-3 text-xs"
            >
              Avbryt
            </Button>
            <Button
              variant="destructive"
              size="sm"
              onClick={handleDelete}
              disabled={isDeleting}
              className="h-8 cursor-pointer px-3 text-xs"
            >
              Radera
            </Button>
          </div>
        </div>
      )}

      {item.page_context && (
        <p className="mt-1.5 truncate text-[11px] text-muted-foreground">
          📍 {item.page_context}
        </p>
      )}
    </div>
  );
};

import { type Identifier, useGetManyAggregate } from "ra-core";

import {
  AvatarFallback,
  AvatarImage,
  Avatar as ShadcnAvatar,
} from "@/components/ui/avatar";

type Sale = {
  id: Identifier;
  first_name?: string;
  last_name?: string;
  avatar?: { src?: string | null } | null;
};

/**
 * Visar avatar + namn för den som skrev en feedback-post.
 * Återanvänder samma sales-uppslag som useGetSalesName (useGetManyAggregate)
 * så uppslagen batchas/cachas av react-query.
 */
export const FeedbackAuthor = ({
  salesId,
  isCurrentUser,
}: {
  salesId?: Identifier;
  isCurrentUser: boolean;
}) => {
  const { data } = useGetManyAggregate<Sale>(
    "sales",
    { ids: salesId != null ? [salesId] : [] },
    { enabled: salesId != null },
  );
  const sale = data?.[0];

  const first = sale?.first_name ?? "";
  const last = sale?.last_name ?? "";
  const initials = `${first.charAt(0)}${last.charAt(0)}`.toUpperCase() || "?";
  const name = isCurrentUser ? "Du" : `${first} ${last}`.trim() || "Okänd";

  return (
    <div className="flex items-center gap-1.5">
      <ShadcnAvatar className="h-5 w-5">
        <AvatarImage src={sale?.avatar?.src ?? undefined} />
        <AvatarFallback className="text-[9px]">{initials}</AvatarFallback>
      </ShadcnAvatar>
      <span className="text-xs font-medium text-foreground">{name}</span>
    </div>
  );
};

