          />
        </TabsContent>
      </Tabs>
    </div>
  );

  if (isMobile) {
    return (
      <>
        <MobileHeader>
          <div>
            <p className="text-xs text-muted-foreground">Översikt</p>
            <h1 className="text-lg font-semibold">Email-statistik</h1>
          </div>
        </MobileHeader>
        <MobileContent
          onRefresh={() =>
            tab === "email"
              ? emailStatsQuery.refetch()
              : scannerLeadStatsQuery.refetch()
          }
        >
          {content}
        </MobileContent>
      </>
    );
  }

  return <main className="mt-1">{content}</main>;
}

