    <div className="flex flex-row flex-wrap gap-4 mt-4">
      {data.map((contact) => (
        <div className="flex flex-row gap-4 items-center" key={contact.id}>
          <Avatar record={contact} />
          <div className="flex flex-col">
            <RouterLink
              to={`/contacts/${contact.id}/show`}
              className="text-sm hover:underline"
            >
              {contact.first_name} {contact.last_name}
            </RouterLink>
            <span className="text-xs text-muted-foreground">
              {contact.title && contact.company_name
                ? translate("resources.contacts.position_at_company", {
                    title: contact.title,
                    company: contact.company_name,
                  })
                : contact.title || contact.company_name}
            </span>
          </div>
        </div>
      ))}
    </div>
  );
};

import {
  format,
  startOfDay,
  startOfMonth,
  startOfWeek,
  subDays,
  subMonths,
  subWeeks,
  isBefore,
} from "date-fns";
import { useGetList } from "ra-core";
import { useMemo } from "react";

import type { Deal, SalesEntry } from "../types";

export type PeriodType = "day" | "week" | "month";

export interface SalesTrackingPeriod {
  periodLabel: string;
  periodStart: string;
  manualSales: number;
  dealRevenue: number;
}

export interface SalesTrackingData {
  periods: SalesTrackingPeriod[];
  totalManual: number;
  totalDeals: number;
  isPending: boolean;
}

function getPeriodStart(date: Date, periodType: PeriodType): Date {
  switch (periodType) {
    case "day":
      return startOfDay(date);
    case "week":
      return startOfWeek(date, { weekStartsOn: 1 });
    case "month":
      return startOfMonth(date);
  }
}

function getPeriodLabel(date: Date, periodType: PeriodType): string {
  switch (periodType) {
    case "day":
      return format(date, "d MMM");
    case "week":
      return `v${format(date, "w")}`;
    case "month":
      return format(date, "MMM yyyy");
  }
}

// Use period-aligned cutoffs so boundary inclusion is predictable
function getCutoffDate(periodType: PeriodType): Date {
  const now = new Date();
  switch (periodType) {
    case "day":
      return startOfDay(subDays(now, 30));
    case "week":
      return startOfWeek(subWeeks(now, 12), { weekStartsOn: 1 });
    case "month":
      return startOfMonth(subMonths(now, 12));
  }
}

// Use format() instead of toISOString() to avoid UTC timezone shifts
function toDateKey(date: Date): string {
  return format(date, "yyyy-MM-dd");
}

// Parse a date-only string (YYYY-MM-DD) safely in local time
function parseDateString(dateStr: string): Date {
  const [year, month, day] = dateStr.split("-").map(Number);
  return new Date(year, month - 1, day);
}

export function aggregatePeriods(
  entries: SalesEntry[],
  deals: Deal[],
  periodType: PeriodType,
): SalesTrackingPeriod[] {
  const cutoff = getCutoffDate(periodType);
  const now = new Date();
  const periodMap = new Map<
    string,
    { label: string; start: string; manual: number; deals: number }
  >();

  // Build all period buckets
  let cursor = getPeriodStart(now, periodType);
  while (!isBefore(cursor, cutoff)) {
    const key = toDateKey(cursor);
    periodMap.set(key, {
      label: getPeriodLabel(cursor, periodType),
      start: key,
      manual: 0,
      deals: 0,
    });
    switch (periodType) {
      case "day":
        cursor = subDays(cursor, 1);
        break;
      case "week":
        cursor = subWeeks(cursor, 1);
        break;
      case "month":
        cursor = subMonths(cursor, 1);
        break;
    }
  }

  // Aggregate manual sales entries
  for (const entry of entries) {
    const entryDate = parseDateString(entry.period_date);
    const periodStart = getPeriodStart(entryDate, periodType);
    const key = toDateKey(periodStart);
    const bucket = periodMap.get(key);
    if (bucket) {
      bucket.manual += entry.amount;
    }
  }

  // Aggregate deal revenue (won deals)
  for (const deal of deals) {
    const dealDate = new Date(deal.expected_closing_date);
    const periodStart = getPeriodStart(dealDate, periodType);
    const key = toDateKey(periodStart);
    const bucket = periodMap.get(key);
    if (bucket) {
      bucket.deals += deal.amount;
    }
  }

  // Sort chronologically (oldest first)
  return Array.from(periodMap.values())
    .sort((a, b) => a.start.localeCompare(b.start))
    .map(({ label, start, manual, deals }) => ({
      periodLabel: label,
      periodStart: start,
      manualSales: manual,
      dealRevenue: deals,
    }));
}

export const useSalesTracking = (periodType: PeriodType): SalesTrackingData => {
  const cutoff = getCutoffDate(periodType);
  const cutoffISO = cutoff.toISOString();

  const { data: entries, isPending: isPendingEntries } = useGetList<SalesEntry>(
    "sales_entries",
    {
      pagination: { perPage: 1000, page: 1 },
      sort: { field: "period_date", order: "ASC" },
      filter: {
        "period_date@gte": cutoffISO,
      },
    },
  );

  const { data: deals, isPending: isPendingDeals } = useGetList<Deal>("deals", {
    pagination: { perPage: 1000, page: 1 },
    sort: { field: "expected_closing_date", order: "ASC" },
    filter: {
      "archived_at@is": null,
      "stage@eq": "won",
      "expected_closing_date@gte": cutoffISO,
    },
  });

  return useMemo(() => {
    const safeEntries = entries ?? [];
    const safeDeals = deals ?? [];

    const periods = aggregatePeriods(safeEntries, safeDeals, periodType);
    const totalManual = periods.reduce((sum, p) => sum + p.manualSales, 0);
    const totalDeals = periods.reduce((sum, p) => sum + p.dealRevenue, 0);

    return {
      periods,
      totalManual,
      totalDeals,
      isPending: isPendingEntries || isPendingDeals,
    };
  }, [entries, deals, periodType, isPendingEntries, isPendingDeals]);
};

import {
  startOfMonth,
  subMonths,
  subDays,
  isAfter,
  isBefore,
  format,
} from "date-fns";
import { useGetList } from "ra-core";
import { useMemo } from "react";

import { totalDealValue } from "../deals/dealUtils";
import { useConfigurationContext } from "../root/ConfigurationContext";
import type { Deal } from "../types";

const CLOSED_STAGES = ["won", "lost"];
const INACTIVE_STAGES = ["won", "lost", "delayed"];

interface MonthlyRevenue {
  month: string;
  won: number;
  pipeline: number;
}

interface StageBreakdown {
  stage: string;
  label: string;
  count: number;
  value: number;
}

export interface DashboardMetrics {
  closedRevenue: number;
  closedRevenuePrev: number;
  pipelineValue: number;
  pipelineValuePrev: number;
  winRate: number;
  winRatePrev: number;
  avgDealSize: number;
  avgDealSizePrev: number;
  monthlyRevenue: MonthlyRevenue[];
  dealsByStage: StageBreakdown[];
  isPending: boolean;
}

export const useDashboardDeals = (): DashboardMetrics => {
  const { dealStages } = useConfigurationContext();

  const { data, isPending } = useGetList<Deal>("deals", {
    pagination: { perPage: 1000, page: 1 },
    sort: { field: "expected_closing_date", order: "ASC" },
    filter: { "archived_at@is": null },
  });

  return useMemo(() => {
    if (!data) {
      return {
        closedRevenue: 0,
        closedRevenuePrev: 0,
        pipelineValue: 0,
        pipelineValuePrev: 0,
        winRate: 0,
        winRatePrev: 0,
        avgDealSize: 0,
        avgDealSizePrev: 0,
        monthlyRevenue: [],
        dealsByStage: [],
        isPending,
      };
    }

    const now = new Date();
    const thisMonthStart = startOfMonth(now);
    const prevMonthStart = startOfMonth(subMonths(now, 1));
    const days90ago = subDays(now, 90);
    const days180ago = subDays(now, 180);
    const months6ago = subMonths(now, 6);
    const months12ago = subMonths(now, 12);

    // Closed revenue (won deals) - current month vs previous
    const wonDeals = data.filter((d) => d.stage === "won");
    const closedRevenue = wonDeals
      .filter((d) => {
        const date = new Date(d.expected_closing_date);
        return !isBefore(date, thisMonthStart);
      })
      .reduce((sum, d) => sum + totalDealValue(d), 0);

    const closedRevenuePrev = wonDeals
      .filter((d) => {
        const date = new Date(d.expected_closing_date);
        return (
          !isBefore(date, prevMonthStart) && isBefore(date, thisMonthStart)
        );
      })
      .reduce((sum, d) => sum + totalDealValue(d), 0);

    // Pipeline value - active stages only
    const activePipelineDeals = data.filter(
      (d) => !INACTIVE_STAGES.includes(d.stage),
    );
    const pipelineValue = activePipelineDeals.reduce(
      (sum, d) => sum + totalDealValue(d),
      0,
    );

    // Pipeline previous month (deals created before this month that were active)
    const pipelineValuePrev = activePipelineDeals
      .filter((d) => {
        const date = new Date(d.created_at);
        return isBefore(date, thisMonthStart);
      })
      .reduce((sum, d) => sum + totalDealValue(d), 0);

    // Win rate - last 90 days vs previous 90 days
    const closedLast90 = data.filter((d) => {
      if (!CLOSED_STAGES.includes(d.stage)) return false;
      const date = new Date(d.updated_at);
      return isAfter(date, days90ago);
    });
    const wonLast90 = closedLast90.filter((d) => d.stage === "won").length;
    const totalClosed90 = closedLast90.length;
    const winRate = totalClosed90 > 0 ? (wonLast90 / totalClosed90) * 100 : 0;

    const closedPrev90 = data.filter((d) => {
      if (!CLOSED_STAGES.includes(d.stage)) return false;
      const date = new Date(d.updated_at);
      return isAfter(date, days180ago) && isBefore(date, days90ago);
    });
    const wonPrev90 = closedPrev90.filter((d) => d.stage === "won").length;
    const totalClosedPrev90 = closedPrev90.length;
    const winRatePrev =
      totalClosedPrev90 > 0 ? (wonPrev90 / totalClosedPrev90) * 100 : 0;

    // Average deal size - won deals last 6 months vs previous 6
    const wonRecent = wonDeals.filter((d) =>
      isAfter(new Date(d.expected_closing_date), months6ago),
    );
    const avgDealSize =
      wonRecent.length > 0
        ? wonRecent.reduce((sum, d) => sum + totalDealValue(d), 0) /
          wonRecent.length
        : 0;

    const wonOlder = wonDeals.filter((d) => {
      const date = new Date(d.expected_closing_date);
      return isAfter(date, months12ago) && isBefore(date, months6ago);
    });
    const avgDealSizePrev =
      wonOlder.length > 0
        ? wonOlder.reduce((sum, d) => sum + totalDealValue(d), 0) /
          wonOlder.length
        : 0;

    // Monthly revenue for line chart (12 months)
    const monthlyRevenue: MonthlyRevenue[] = [];
    for (let i = 11; i >= 0; i--) {
      const monthStart = startOfMonth(subMonths(now, i));
      const monthEnd = startOfMonth(subMonths(now, i - 1));
      const monthKey = format(monthStart, "MMM yyyy");

      const monthWon = data
        .filter((d) => {
          if (d.stage !== "won") return false;
          const date = new Date(d.expected_closing_date);
          return !isBefore(date, monthStart) && isBefore(date, monthEnd);
        })
        .reduce((sum, d) => sum + totalDealValue(d), 0);

      const monthPipeline = data
        .filter((d) => {
          if (INACTIVE_STAGES.includes(d.stage)) return false;
          const date = new Date(d.expected_closing_date);
          return !isBefore(date, monthStart) && isBefore(date, monthEnd);
        })
        .reduce((sum, d) => sum + totalDealValue(d), 0);

      monthlyRevenue.push({
        month: monthKey,
        won: monthWon,
        pipeline: monthPipeline,
      });
    }

    // Deals by stage (active pipeline stages only)
    const dealsByStage: StageBreakdown[] = dealStages
      .filter((s) => !CLOSED_STAGES.includes(s.value))
      .map((stage) => {
        const stageDeals = data.filter((d) => d.stage === stage.value);
        return {
          stage: stage.value,
          label: stage.label,
          count: stageDeals.length,
          value: stageDeals.reduce((sum, d) => sum + totalDealValue(d), 0),
        };
      })
      .filter((s) => s.count > 0);

    return {
      closedRevenue,
      closedRevenuePrev,
      pipelineValue,
      pipelineValuePrev,
      winRate,
      winRatePrev,
      avgDealSize,
      avgDealSizePrev,
      monthlyRevenue,
      dealsByStage,
      isPending,
    };
  }, [data, isPending, dealStages]);
};

