import { useQuery } from "@tanstack/react-query";
import { CalendarClock, Coins, PiggyBank, Wallet } from "lucide-react";
import { useDataProvider } from "ra-core";
import { memo } from "react";

import { Skeleton } from "@/components/ui/skeleton";

import { monthlyAmount } from "../fortnox/liquidity";
import type { CrmDataProvider } from "../providers/types";
import { KpiCard } from "./KpiCard";

/** Compact SEK, matching the sales KPI row: 79 373 → "79k". */
function sek(value: number): string {
  const abs = Math.abs(value);
  if (abs >= 1_000_000) {
    return `${(value / 1_000_000).toLocaleString("sv-SE", {
      maximumFractionDigits: 1,
    })} MSEK`;
  }
  if (abs >= 10_000) {
    return `${Math.round(value / 1_000).toLocaleString("sv-SE")}k kr`;
  }
  return `${Math.round(value).toLocaleString("sv-SE")} kr`;
}

/**
 * A financial glance at the top of the dashboard: result this year, MRR, net
 * runrate and outstanding receivables — the Ekonomi/Likviditet headline numbers
 * lifted to the front page. All read from data already mirrored, so it costs
 * nothing new.
 */
export const FinancialKpiRow = memo(() => {
  const dataProvider = useDataProvider<CrmDataProvider>();
  const thisYear = new Date().getFullYear().toString();

  const result = useQuery({
    queryKey: ["fortnox", "result-monthly"],
    queryFn: () => dataProvider.getFortnoxResultMonthly(),
  });
  const revenue = useQuery({
    queryKey: ["liquidity", "recurring-revenue"],
    queryFn: () => dataProvider.getRecurringRevenue(),
  });
  const subs = useQuery({
    queryKey: ["subscriptions"],
    queryFn: () => dataProvider.getSubscriptions(),
  });
  const invoices = useQuery({
    queryKey: ["fortnox", "supplier-and-invoices", "list"],
    queryFn: () => dataProvider.getFortnoxInvoices(),
  });

  const isPending =
    result.isPending ||
    revenue.isPending ||
    subs.isPending ||
    invoices.isPending;

  if (isPending) {
    return (
      <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
        {Array.from({ length: 4 }).map((_, i) => (
          <Skeleton key={i} className="h-24 rounded-xl" />
        ))}
      </div>
    );
  }

  const yearResult = (result.data ?? [])
    .filter((r) => r.month.startsWith(thisYear))
    .reduce((sum, r) => sum + r.result, 0);

  const mrr = (revenue.data ?? []).reduce(
    (sum, d) => sum + monthlyAmount(d.recurring_amount, d.recurring_interval),
    0,
  );

  const activeCostMonthly = (subs.data ?? [])
    .filter((s) => s.status === "active")
    .reduce((sum, s) => sum + s.monthly_amount, 0);

  const netRunrate = mrr - activeCostMonthly;

  const unpaid = (invoices.data ?? []).filter(
    (i) => i.status === "unpaid" || i.status === "overdue",
  );
  const unpaidBalance = unpaid.reduce((sum, i) => sum + (i.balance ?? 0), 0);

  return (
    <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
      <KpiCard
        title={`Resultat ${thisYear}`}
        value={sek(yearResult)}
        icon={PiggyBank}
      />
      <KpiCard
        title="MRR (återkommande)"
        value={`${sek(mrr)}/mån`}
        icon={Coins}
      />
      <KpiCard
        title="Netto runrate"
        value={`${sek(netRunrate)}/mån`}
        icon={CalendarClock}
      />
      <KpiCard
        title={
          unpaid.length > 0 ? `Obetalt (${unpaid.length} fakt.)` : "Obetalt"
        }
        value={sek(unpaidBalance)}
        icon={Wallet}
      />
    </div>
  );
});

import { DollarSign } from "lucide-react";
import { useGetIdentity, useGetList, useTranslate } from "ra-core";
import { Link } from "react-router";
import { ReferenceField } from "@/components/admin/reference-field";
import { Card } from "@/components/ui/card";

import { SimpleList } from "../simple-list/SimpleList";
import { CompanyAvatar } from "../companies/CompanyAvatar";
import { findDealLabel } from "../deals/dealUtils";
import { useConfigurationContext } from "../root/ConfigurationContext";
import type { Deal } from "../types";

/**
 * This component displays the deals pipeline for the current user.
 * It's currently not used in the application but can be added to the dashboard.
 */
export const DealsPipeline = () => {
  const translate = useTranslate();
  const { identity } = useGetIdentity();
  const { dealStages, dealPipelineStatuses, currency } =
    useConfigurationContext();
  const { data, total, isPending } = useGetList<Deal>(
    "deals",
    {
      pagination: { page: 1, perPage: 10 },
      sort: { field: "last_seen", order: "DESC" },
      filter: { "stage@neq": "lost", sales_id: identity?.id },
    },
    { enabled: Number.isInteger(identity?.id) },
  );

  const getOrderedDeals = (data?: Deal[]): Deal[] | undefined => {
    if (!data) {
      return;
    }
    const deals: Deal[] = [];
    dealStages
      .filter((stage) => !dealPipelineStatuses.includes(stage.value))
      .forEach((stage) =>
        data
          .filter((deal) => deal.stage === stage.value)
          .forEach((deal) => deals.push(deal)),
      );
    return deals;
  };

  return (
    <>
      <div className="flex items-center mb-4">
        <div className="ml-8 mr-8 flex">
          <DollarSign className="text-muted-foreground w-6 h-6" />
        </div>
        <Link
          className="text-xl font-semibold text-muted-foreground hover:underline"
          to="/deals"
        >
          {translate("crm.dashboard.deals_pipeline")}
        </Link>
      </div>
      <Card>
        <SimpleList<Deal>
          resource="deals"
          linkType="show"
          data={getOrderedDeals(data)}
          total={total}
          isPending={isPending}
          primaryText={(deal) => deal.name}
          secondaryText={(deal) =>
            `${deal.amount.toLocaleString("en-US", {
              notation: "compact",
              style: "currency",
              currency,
              currencyDisplay: "narrowSymbol",
              minimumSignificantDigits: 3,
            })} , ${findDealLabel(dealStages, deal.stage)}`
          }
          leftAvatar={(deal) => (
            <ReferenceField
              source="company_id"
              record={deal}
              reference="companies"
              resource="deals"
              link={false}
            >
              <CompanyAvatar width={20} height={20} />
            </ReferenceField>
          )}
        />
      </Card>
    </>
  );
};

import { ResponsiveBar } from "@nivo/bar";
import { format, startOfMonth } from "date-fns";
import { TrendingUp } from "lucide-react";
import { useGetList, useTranslate } from "ra-core";
import { memo, useMemo } from "react";

import { findDealLabel, totalDealValue } from "../deals/dealUtils";
import { useConfigurationContext } from "../root/ConfigurationContext";
import type { Deal } from "../types";

const sixMonthsAgo = new Date(
  new Date().setMonth(new Date().getMonth() - 6),
).toISOString();

const DEFAULT_LOCALE = "en-US";

const getMonthKey = (date: string | undefined) => {
  if (!date) {
    return null;
  }
  const parsed = new Date(date);
  if (Number.isNaN(parsed.getTime())) {
    return null;
  }
  return startOfMonth(parsed).toISOString();
};

export const DealsChart = memo(() => {
  const translate = useTranslate();
  const { dealStages, currency } = useConfigurationContext();
  const acceptedLanguages = navigator
    ? navigator.languages || [navigator.language]
    : [DEFAULT_LOCALE];
  const wonLabel = findDealLabel(dealStages, "won") ?? "Won";
  const pendingLabel = translate("crm.dashboard.deals_pending", {
    _: "In Progress",
  });
  const lostLabel = findDealLabel(dealStages, "lost") ?? "Lost";

  const { data, isPending } = useGetList<Deal>("deals", {
    pagination: { perPage: 1000, page: 1 },
    sort: {
      field: "expected_closing_date",
      order: "ASC",
    },
    filter: {
      "expected_closing_date@gte": sixMonthsAgo,
      "archived_at@is": null,
    },
  });

  const months = useMemo(() => {
    if (!data) return [];

    const dealsByMonth = data.reduce(
      (acc, deal) => {
        const month = getMonthKey(deal.expected_closing_date);
        if (!month) {
          return acc;
        }

        if (!acc[month]) {
          acc[month] = [];
        }
        acc[month].push(deal);
        return acc;
      },
      {} as Record<string, Deal[]>,
    );

    return Object.keys(dealsByMonth)
      .sort((a, b) => new Date(a).getTime() - new Date(b).getTime())
      .map((month) => {
        const monthDeals = dealsByMonth[month];
        return {
          date: format(new Date(month), "MMM"),
          won: monthDeals
            .filter((deal) => deal.stage === "won")
            .reduce((acc, deal) => acc + totalDealValue(deal), 0),
          pending: monthDeals
            .filter((deal) => !["won", "lost"].includes(deal.stage))
            .reduce((acc, deal) => acc + totalDealValue(deal), 0),
          lost: monthDeals
            .filter((deal) => deal.stage === "lost")
            .reduce((acc, deal) => acc - deal.amount, 0),
        };
      });
  }, [data]);

  if (isPending)
    return (
      <div className="flex flex-col">
        <div className="flex items-center mb-4">
          <div className="mr-3 flex">
            <TrendingUp className="text-muted-foreground w-6 h-6" />
          </div>
          <h2 className="text-xl font-semibold text-muted-foreground">
            {translate("crm.dashboard.deals_chart")}
          </h2>
        </div>
        <div className="h-[400px] flex items-center justify-center">
          <div className="w-full h-full animate-pulse bg-muted rounded-md" />
        </div>
      </div>
    );
  const range = months.reduce(
    (acc, month) => {
      acc.min = Math.min(acc.min, month.lost);
      acc.max = Math.max(acc.max, month.won + month.pending);
      return acc;
    },
    { min: 0, max: 0 },
  );
  return (
    <div className="flex flex-col">
      <div className="flex items-center mb-4">
        <div className="mr-3 flex">
          <TrendingUp className="text-muted-foreground w-6 h-6" />
        </div>
        <h2 className="text-xl font-semibold text-muted-foreground">
          {translate("crm.dashboard.deals_chart")}
        </h2>
      </div>
      <div className="h-[400px]">
        <ResponsiveBar
          data={months}
          indexBy="date"
          keys={["won", "pending", "lost"]}
          colors={["#61cdbb", "#f4a261", "#e25c3b"]}
          margin={{ top: 30, right: 50, bottom: 30, left: 0 }}
          padding={0.3}
          valueScale={{
            type: "linear",
            min: range.min * 1.2,
            max: range.max * 1.2,
          }}
          indexScale={{ type: "band", round: true }}
          enableGridX={true}
          enableGridY={false}
          enableLabel={false}
          tooltip={({ id, value, indexValue, color }) => {
            const label =
              id === "won"
                ? wonLabel
                : id === "pending"
                  ? pendingLabel
                  : lostLabel;
            return (
              <div className="p-2 bg-secondary rounded shadow inline-flex items-center gap-1 text-secondary-foreground">
                <span
                  className="inline-block w-3 h-3 rounded-sm mr-1"
                  style={{ backgroundColor: color }}
                />
                <strong>
                  {indexValue} – {label}:
                </strong>
                &nbsp;{value > 0 ? "+" : ""}
                {Math.abs(value).toLocaleString(
                  acceptedLanguages.at(0) ?? DEFAULT_LOCALE,
                  {
                    style: "currency",
                    currency,
                  },
                )}
              </div>
            );
          }}
          axisTop={{
            tickSize: 0,
            tickPadding: 12,
            style: {
              ticks: {
                text: {
                  fill: "var(--color-muted-foreground)",
                },
              },
              legend: {
                text: {
                  fill: "var(--color-muted-foreground)",
                },
              },
            },
          }}
          axisBottom={{
            legendPosition: "middle",
            legendOffset: 50,
            tickSize: 0,
            tickPadding: 12,
            style: {
              ticks: {
                text: {
                  fill: "var(--color-muted-foreground)",
                },
              },
              legend: {
                text: {
                  fill: "var(--color-muted-foreground)",
                },
              },
            },
          }}
          axisLeft={null}
          axisRight={{
            format: (v: any) => `${Math.abs(v / 1000)}k`,
            tickValues: 8,
            style: {
              ticks: {
                text: {
                  fill: "var(--color-muted-foreground)",
                },
              },
              legend: {
                text: {
                  fill: "var(--color-muted-foreground)",
                },
              },
            },
          }}
          legends={[
            {
              dataFrom: "keys",
              anchor: "top-right",
              direction: "row",
              translateY: -25,
              itemWidth: 100,
              itemHeight: 20,
              itemDirection: "left-to-right",
              symbolSize: 12,
              symbolShape: "square",
              itemTextColor: "var(--color-muted-foreground)",
              data: [
                {
                  id: "won",
                  label: wonLabel,
                  color: "#61cdbb",
                },
                {
                  id: "pending",
                  label: pendingLabel,
                  color: "#f4a261",
                },
                {
                  id: "lost",
                  label: lostLabel,
                  color: "#e25c3b",
                },
              ],
            },
          ]}
          markers={
            [
              {
                axis: "y",
                value: 0,
                lineStyle: {
                  stroke: "#f47560",
                  strokeWidth: 1,
                },
              },
            ] as any
          }
        />
      </div>
    </div>
  );
});

import { Layers } from "lucide-react";
import { useTranslate } from "ra-core";
import { memo } from "react";

import { Badge } from "@/components/ui/badge";
import { Card, CardContent } from "@/components/ui/card";
import { Progress } from "@/components/ui/progress";

import { useConfigurationContext } from "../root/ConfigurationContext";
import { useDashboardDeals } from "./useDashboardDeals";

const DEFAULT_LOCALE = "en-US";

const STAGE_COLORS: Record<string, string> = {
  opportunity: "#3b82f6",
  "generating-proposal": "#8b5cf6",
  "proposal-sent": "#f59e0b",
  "in-negociation": "#ef4444",
  delayed: "#6b7280",
};

export const DealStageFunnel = memo(() => {
  const translate = useTranslate();
  const { currency } = useConfigurationContext();
  const { dealsByStage, isPending } = useDashboardDeals();
  const locale =
    navigator?.languages?.[0] ?? navigator?.language ?? DEFAULT_LOCALE;

  if (isPending || dealsByStage.length === 0) {
    return null;
  }

  const maxValue = Math.max(...dealsByStage.map((s) => s.value));

  return (
    <div className="flex flex-col gap-2">
      <div className="flex items-center mb-2">
        <div className="mr-3 flex">
          <Layers className="text-muted-foreground w-6 h-6" />
        </div>
        <h2 className="text-xl font-semibold text-muted-foreground">
          {translate("crm.dashboard.deal_stage_breakdown", {
            _: "Deal Stage Breakdown",
          })}
        </h2>
      </div>
      <Card>
        <CardContent className="flex flex-col gap-4">
          {dealsByStage.map((stage) => (
            <div key={stage.stage} className="flex flex-col gap-1.5">
              <div className="flex items-center justify-between text-sm">
                <div className="flex items-center gap-2">
                  <span
                    className="w-2.5 h-2.5 rounded-full"
                    style={{
                      backgroundColor: STAGE_COLORS[stage.stage] ?? "#6b7280",
                    }}
                  />
                  <span className="font-medium">{stage.label}</span>
                  <Badge variant="secondary" className="text-xs">
                    {stage.count}
                  </Badge>
                </div>
                <span className="text-muted-foreground font-medium">
                  {stage.value.toLocaleString(locale, {
                    style: "currency",
                    currency,
                    maximumFractionDigits: 0,
                  })}
                </span>
              </div>
              <Progress
                value={maxValue > 0 ? (stage.value / maxValue) * 100 : 0}
                className="h-2"
                style={
                  {
                    "--color-primary": STAGE_COLORS[stage.stage] ?? "#6b7280",
                  } as React.CSSProperties
                }
              />
            </div>
