  if (!model) return null;

  const attention = model.rows
    .filter((row) => row.category === "poor" || row.category === "watch")
    .slice(0, 5);

  return (
    <div className="flex flex-col gap-6">
      <header className="flex flex-col gap-4 lg:flex-row lg:items-end lg:justify-between">
        <div>
          <div className="hidden items-center gap-2 md:flex">
            <BarChart3 className="size-5 text-primary" />
            <h1 className="text-2xl font-semibold tracking-tight">Kundradar</h1>
          </div>
          <p className="mt-1 max-w-2xl text-sm text-muted-foreground">
            Samma verifierade webbstatistik som i kundbilden och kundrapporten,
            samlad för hela portföljen.
          </p>
        </div>
        <Select value={period} onValueChange={onPeriodChange}>
          <SelectTrigger className="w-full lg:w-56">
            <SelectValue />
          </SelectTrigger>
          <SelectContent>
            {periodOptions().map((option) => (
              <SelectItem key={option} value={option}>
                {new Date(`${option}T00:00:00Z`).toLocaleDateString("sv-SE", {
                  month: "long",
                  year: "numeric",
                  timeZone: "UTC",
                })}
              </SelectItem>
            ))}
          </SelectContent>
        </Select>
      </header>

      <PipelineFailuresCard />

      <div className="grid grid-cols-2 gap-3 xl:grid-cols-7">
        <SummaryCard
          icon={Users}
          label="Levererade sajter"
          value={String(model.metrics.customers)}
          helper={`${model.metrics.analyzedCustomers} med någon analys`}
