        <SummaryCard
          icon={Globe2}
          label="Google-klick"
          value={model.metrics.clicks?.toLocaleString("sv-SE") ?? "Data saknas"}
          helper={`${model.metrics.searchCustomers} kunder ingår`}
        />
        <SummaryCard
          icon={TrendingUp}
          label="Förbättrats"
          value={String(model.metrics.improved)}
          helper={`${model.metrics.declined} har försämrats`}
