          helper={`${model.rows.filter((row) => row.currentSnapshot?.performance_score != null).length} kunder ingår`}
        />
        <SummaryCard
          icon={FileCheck2}
          label="Teknisk grund"
          value={`${model.metrics.technicalHealthy}/${model.metrics.technicalCustomers}`}
          helper="kunder med godkänd teknisk status"
        />
        <SummaryCard
          icon={Gauge}
          label="Core Web Vitals"
          value={`${model.metrics.healthyCoreWebVitals}/${model.metrics.coreWebVitalsCustomers}`}
          helper="kunder med bra verklig fältdata"
        />
        <SummaryCard
          icon={Send}
          label="Rapporter skickade"
          value={`${model.reports.sent}/${model.metrics.customers}`}
          helper={`${model.reports.draft + model.reports.missing + model.reports.failed} återstår · ${model.reports.archived} arkiverade`}
        />
      </div>

      <div className="grid gap-3 sm:grid-cols-2 xl:grid-cols-5">
        {CATEGORY_ORDER.map((item) => (
          <Card key={item} className="gap-2 py-4">
            <CardContent className="flex items-center justify-between px-4">
              <div>
                <p className="text-xs text-muted-foreground">
                  {CATEGORY_LABELS[item]}
                </p>
                <p className="mt-1 text-2xl font-semibold tabular-nums">
                  {model.counts[item]}
                </p>
              </div>
              {item === "very_good" || item === "good" ? (
                <CheckCircle2 className="size-5 text-emerald-600" />
              ) : item === "poor" ? (
                <TrendingDown className="size-5 text-red-600" />
