                        ? ` · ${selected.seo_checks.stale_count} sidor med datum äldre än 6 mån`
                        : ""}
                      . Färskt innehåll ger fler AI-citeringar.
                    </p>
                  ) : null}
                </CardContent>
              </Card>

              <Card>
                <CardHeader>
                  <CardTitle className="flex items-center gap-2 text-base">
                    <MapPin className="size-4" />
                    Lokal synlighet
                  </CardTitle>
                </CardHeader>
                <CardContent className="space-y-4 text-sm">
                  {!business ? (
                    <p className="text-muted-foreground">
                      Google Business kunde inte kontrolleras.
                    </p>
                  ) : business.found ? (
                    <>
                      <p className="text-3xl font-semibold tabular-nums">
                        {business.rating?.toLocaleString("sv-SE") ?? "—"} / 5
                      </p>
                      <p className="text-muted-foreground">
                        {business.reviews_count ?? 0} recensioner
                        <span className="block text-xs">
                          Nuläge · uppmätt{" "}
                          {new Date(selected.fetched_at).toLocaleDateString(
                            "sv-SE",
                          )}
                        </span>
                      </p>
                      {reviewVelocity != null ? (
                        <p
                          className={
                            reviewVelocity > 0
                              ? "text-green-700"
                              : reviewVelocity < 0
                                ? "text-red-700"
                                : "text-muted-foreground"
                          }
                        >
                          {reviewVelocity > 0
                            ? `+${reviewVelocity} nya recensioner sedan föregående period`
                            : reviewVelocity < 0
                              ? `${Math.abs(reviewVelocity)} recensioner färre än föregående period`
                              : "Inga nya recensioner sedan föregående period"}
                        </p>
                      ) : null}
                      <p>
                        En jämn ström av nya recensioner stärker både lokal
                        synlighet och förtroende — färskhet väger tyngre än
                        engångsvolym.
                      </p>
                    </>
                  ) : (
                    <p className="text-red-700">
                      Ingen verifierad profil hittades. Företaget riskerar att
                      inte synas på Google Maps.
                    </p>
                  )}
                </CardContent>
              </Card>
            </div>

            <Card>
              <CardHeader>
                <CardTitle className="flex items-center gap-2 text-base">
                  <MapPin className="size-4" />
                  Lokal placering · kartpaket
                </CardTitle>
              </CardHeader>
              <CardContent>
                {selected.local_rank && selected.local_rank.length > 0 ? (
                  <div className="space-y-2">
                    {selected.local_rank.map((rank) => (
                      <div
                        key={rank.keyword}
                        className="flex items-center justify-between gap-2 border-b py-2 text-sm last:border-0"
                      >
                        <span className="truncate" title={rank.keyword}>
                          {rank.keyword}
                        </span>
                        <span
                          className={`whitespace-nowrap font-medium ${localRankColor(rank.position, rank.found)}`}
                        >
                          {rank.found && rank.position != null
                            ? `Plats ${rank.position}`
                            : "Utanför kartpaketet"}
                        </span>
                      </div>
                    ))}
                  </div>
                ) : (
                  <p className="text-sm text-muted-foreground">
                    Inga lokala sökord spårade. Lägg till sökord på Kund-fliken
                    (kräver DataForSEO-konfiguration).
                  </p>
                )}
                <p className="mt-3 text-xs text-muted-foreground">
                  Placering i Googles kartpaket för "tjänst nära mig"-sökningar
                  — ofta högst ROI för lokala företag.
                </p>
              </CardContent>
            </Card>

            <Card>
              <CardHeader>
                <CardTitle className="flex items-center gap-2 text-base">
                  <Phone className="size-4" />
                  Kundåtgärder · Google Business
                </CardTitle>
              </CardHeader>
              <CardContent>
                {selected.gbp_actions ? (
                  <div className="grid gap-3 sm:grid-cols-3">
                    <div className="rounded-md border p-3">
                      <p className="text-2xl font-semibold tabular-nums">
                        {selected.gbp_actions.calls.toLocaleString("sv-SE")}
                      </p>
                      <p className="text-xs text-muted-foreground">Samtal</p>
                    </div>
                    <div className="rounded-md border p-3">
                      <p className="text-2xl font-semibold tabular-nums">
                        {selected.gbp_actions.direction_requests.toLocaleString(
                          "sv-SE",
                        )}
                      </p>
                      <p className="text-xs text-muted-foreground">
                        Vägbeskrivningar
                      </p>
                    </div>
                    <div className="rounded-md border p-3">
                      <p className="text-2xl font-semibold tabular-nums">
                        {selected.gbp_actions.website_clicks.toLocaleString(
                          "sv-SE",
                        )}
                      </p>
                      <p className="text-xs text-muted-foreground">Webbklick</p>
                    </div>
                  </div>
                ) : (
                  <p className="text-sm text-muted-foreground">
                    Inga åtgärdsdata. Kräver att kundens Google Business
                    location-ID fylls i på Kund-fliken och att kontot har
                    business.manage-behörighet.
                  </p>
                )}
                <p className="mt-3 text-xs text-muted-foreground">
                  Direkta kundåtgärder från Google-kartan — närmast affär av all
                  synlighetsdata.
                </p>
              </CardContent>
            </Card>

            {selected.competitors && selected.competitors.length > 0 ? (
              <Card>
                <CardHeader>
                  <CardTitle className="flex items-center gap-2 text-base">
                    <BarChart3 className="size-4" />
                    Konkurrentjämförelse
                  </CardTitle>
                </CardHeader>
                <CardContent>
                  <div className="space-y-1">
                    <div className="flex items-center justify-between border-b py-2 text-sm font-medium">
                      <span>Er sajt</span>
                      <span className="text-muted-foreground">
                        Prestanda {selected.performance_score ?? "—"} · SEO{" "}
                        {selected.seo_score ?? "—"} · LCP{" "}
                        {seconds(selected.pagespeed?.lcp_ms ?? null)}
                      </span>
                    </div>
                    {selected.competitors.map((c) => (
                      <div
                        key={c.url}
                        className="flex items-center justify-between gap-2 border-b py-2 text-sm last:border-0"
                      >
                        <span className="truncate" title={c.url}>
                          {hostnameLabel(c.url)}
                        </span>
                        <span className="whitespace-nowrap text-muted-foreground">
                          Prestanda {c.performance_score ?? "—"} · SEO{" "}
                          {c.seo_score ?? "—"} · LCP {seconds(c.lcp_ms)}
                        </span>
                      </div>
                    ))}
                  </div>
                  <p className="mt-3 text-xs text-muted-foreground">
                    Snabbare laddtid och högre poäng än konkurrenterna är ett
                    konkret säljargument. Mätt mobilt. Lägg till konkurrenter på
                    Kund-fliken.
                  </p>
                </CardContent>
              </Card>
            ) : null}
          </TabsContent>

          <TabsContent value="reports" className="mt-5 space-y-4">
            <div className="flex items-center justify-between gap-3">
              <div>
                <h3 className="font-semibold">Kundrapporter</h3>
                <p className="text-sm text-muted-foreground">
                  HTML-mejl och privat PDF från samma verifierade rapportdata.
                </p>
              </div>
              <Button onClick={openNewReport}>
                <FileText className="size-4" />
                Ny rapport
              </Button>
            </div>
            {reports?.length ? (
              <div className="space-y-2">
                {reports.map((report) => (
                  <div
                    key={report.id}
                    className={`flex flex-wrap items-center justify-between gap-3 rounded-lg border p-4 ${
                      report.status === "archived" ? "opacity-65" : ""
                    }`}
                  >
                    <button
                      type="button"
                      onClick={() => openExistingReport(Number(report.id))}
                      className="text-left"
                    >
                      <p className="font-medium">
                        {new Date(
                          `${report.period}T00:00:00Z`,
                        ).toLocaleDateString("sv-SE", {
                          month: "long",
                          year: "numeric",
                          timeZone: "UTC",
                        })}
                      </p>
                      <p className="text-xs text-muted-foreground">
                        Skapad{" "}
                        {new Date(report.created_at).toLocaleDateString(
                          "sv-SE",
                        )}
                        {report.data_period_start && report.data_period_end
                          ? ` · period ${formatDate(report.data_period_start)}–${formatDate(report.data_period_end)}`
                          : ""}
                        {report.status === "sent" && report.sent_at
                          ? ` · skickad ${new Date(report.sent_at).toLocaleDateString("sv-SE")} till ${report.recipient_email ?? "—"}`
                          : report.error
                            ? ` · ${report.error}`
                            : ` · ${report.view_model?.coverage.available ?? "—"}/${report.view_model?.coverage.total ?? "—"} datakällor`}
                      </p>
                    </button>
                    <div className="flex items-center gap-2">
                      <Badge
                        variant="outline"
                        className={REPORT_STATUS_STYLES[report.status]}
                      >
                        {REPORT_STATUS_LABELS[report.status]}
                      </Badge>
                      {report.pdf_storage_path ? (
                        <Button
                          type="button"
                          variant="outline"
                          size="icon"
                          onClick={() => downloadPdf(Number(report.id))}
                          aria-label="Ladda ner PDF"
                        >
                          <Download className="size-4" />
                        </Button>
                      ) : null}
                      {report.status !== "archived" ? (
                        <Button
                          type="button"
                          variant="outline"
                          size="icon"
                          onClick={() => archiveReport(Number(report.id))}
                          aria-label="Arkivera rapport"
                        >
                          <Archive className="size-4" />
                        </Button>
                      ) : null}
                    </div>
                  </div>
                ))}
              </div>
            ) : (
              <p className="rounded-lg border border-dashed p-6 text-center text-sm text-muted-foreground">
                Inga rapporter skapade ännu.
              </p>
            )}
          </TabsContent>
        </Tabs>
      </CardContent>

      <MonthlyReportModal
        company={company}
        reportId={selectedReportId}
        open={reportOpen}
        initialPeriod={
          selected.period_start && selected.period_end
            ? { start: selected.period_start, end: selected.period_end }
            : null
        }
        onOpenChange={(open) => {
          setReportOpen(open);
          if (!open && reportQuery) {
            const nextParams = new URLSearchParams(searchParams);
            nextParams.delete("report");
            setSearchParams(nextParams, { replace: true });
          }
        }}
        onSent={() => refetchReports()}
      />
    </Card>
  );
}

import { useState, useEffect, useCallback } from "react";
import { useNotify } from "ra-core";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
  DialogTrigger,
} from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import { Badge } from "@/components/ui/badge";
import { Switch } from "@/components/ui/switch";
import {
  Settings2,
  Plus,
  Trash2,
  Play,
  Loader2,
  Zap,
  Clock,
  RefreshCw,
} from "lucide-react";
import { supabase } from "../providers/supabase/supabase";

interface SearchProfile {
  id?: number;
  name: string;
  query_template: string;
  branch: string;
  city: string;
  extra_keywords: string[];
  min_rating: number;
  max_results: number;
  is_active: boolean;
  auto_enrich: boolean;
  last_run_at?: string;
  last_run_results?: number;
  total_leads_generated?: number;
}

const DEFAULT_PROFILE: Omit<SearchProfile, "id"> = {
  name: "",
  query_template: "{bransch} i {stad}",
  branch: "",
  city: "",
  extra_keywords: [],
  min_rating: 0,
  max_results: 20,
  is_active: true,
  auto_enrich: true,
};

export const SearchProfiles = () => {
  const [open, setOpen] = useState(false);
  const [profiles, setProfiles] = useState<SearchProfile[]>([]);
  const [editingProfile, setEditingProfile] = useState<SearchProfile | null>(
    null,
  );
  const [isLoading, setIsLoading] = useState(false);
  const [isRunning, setIsRunning] = useState<number | null>(null);
  const [showForm, setShowForm] = useState(false);
  const notify = useNotify();

  const fetchProfiles = useCallback(async () => {
    setIsLoading(true);
    try {
      const { data, error } = await supabase
        .from("search_profiles")
        .select("*")
        .order("created_at", { ascending: false });

      if (error) throw error;
      setProfiles(data ?? []);
    } catch {
      notify("Kunde inte ladda sökprofiler", { type: "error" });
    } finally {
      setIsLoading(false);
    }
  }, [notify]);

  useEffect(() => {
    if (open) {
      fetchProfiles();
    }
  }, [open, fetchProfiles]);

  const handleSave = async () => {
    if (!editingProfile) return;

    if (!editingProfile.branch.trim() || !editingProfile.city.trim()) {
      notify("Bransch och stad krävs", { type: "warning" });
      return;
    }

    const profileName =
      editingProfile.name || `${editingProfile.branch} ${editingProfile.city}`;

    const profileData = {
      name: profileName,
      query_template: editingProfile.query_template,
      branch: editingProfile.branch,
      city: editingProfile.city,
      extra_keywords: editingProfile.extra_keywords,
      min_rating: editingProfile.min_rating,
      max_results: editingProfile.max_results,
      is_active: editingProfile.is_active,
      auto_enrich: editingProfile.auto_enrich,
      updated_at: new Date().toISOString(),
    };

    try {
      if (editingProfile.id) {
        const { error } = await supabase
          .from("search_profiles")
          .update(profileData)
          .eq("id", editingProfile.id);
        if (error) throw error;
        notify("Profil uppdaterad", { type: "success" });
      } else {
        const { error } = await supabase
          .from("search_profiles")
          .insert(profileData);
        if (error) throw error;
        notify("Profil skapad", { type: "success" });
      }

      setEditingProfile(null);
      setShowForm(false);
      fetchProfiles();
    } catch {
      notify("Kunde inte spara profil", { type: "error" });
    }
  };

  const handleDelete = async (id: number) => {
    try {
      const { error } = await supabase
        .from("search_profiles")
        .delete()
        .eq("id", id);
      if (error) throw error;
      notify("Profil borttagen", { type: "success" });
      fetchProfiles();
    } catch {
      notify("Kunde inte ta bort profil", { type: "error" });
    }
  };

  const handleToggleActive = async (id: number, isActive: boolean) => {
    try {
      const { error } = await supabase
        .from("search_profiles")
        .update({ is_active: isActive, updated_at: new Date().toISOString() })
        .eq("id", id);
      if (error) throw error;
      setProfiles((prev) =>
        prev.map((p) => (p.id === id ? { ...p, is_active: isActive } : p)),
      );
    } catch {
      notify("Kunde inte uppdatera profil", { type: "error" });
    }
  };

  const handleRunProfile = async (profileId: number) => {
    setIsRunning(profileId);
    try {
      const {
        data: { session },
      } = await supabase.auth.getSession();

      if (!session) {
        notify("Du måste vara inloggad", { type: "error" });
        return;
      }

      const response = await fetch(
        `${import.meta.env.VITE_SUPABASE_URL}/functions/v1/auto_scrape`,
        {
          method: "POST",
          headers: {
            "Content-Type": "application/json",
            Authorization: `Bearer ${session.access_token}`,
          },
          body: JSON.stringify({ profile_id: profileId }),
        },
      );

      if (!response.ok) {
        let errorMsg = `HTTP ${response.status}`;
        try {
          const errorBody = await response.json();
          errorMsg = errorBody.message || errorMsg;
        } catch {
          errorMsg = await response.text().catch(() => errorMsg);
        }
        throw new Error(errorMsg);
      }

      const result = await response.json();

      if (!result.summary) {
        notify(result.message || "Inga resultat", { type: "info" });
        fetchProfiles();
        return;
      }

      const summary = result.summary;
      notify(
        `${summary.total_new_leads} nya leads importerade, ${summary.total_enriched} enrichade, ${summary.total_duplicates_skipped} dubbletter skippade`,
        { type: "success" },
      );

      fetchProfiles();
    } catch (error) {
      notify(`Fel: ${(error as Error).message}`, { type: "error" });
    } finally {
      setIsRunning(null);
    }
  };

  const handleRunAll = async () => {
    setIsRunning(-1);
    try {
      const {
        data: { session },
      } = await supabase.auth.getSession();

      if (!session) {
        notify("Du måste vara inloggad", { type: "error" });
        return;
      }

      const response = await fetch(
        `${import.meta.env.VITE_SUPABASE_URL}/functions/v1/auto_scrape`,
        {
          method: "POST",
          headers: {
            "Content-Type": "application/json",
            Authorization: `Bearer ${session.access_token}`,
          },
          body: JSON.stringify({}),
        },
      );

      if (!response.ok) {
        let errorMsg = `HTTP ${response.status}`;
        try {
          const errorBody = await response.json();
          errorMsg = errorBody.message || errorMsg;
        } catch {
          errorMsg = await response.text().catch(() => errorMsg);
        }
        throw new Error(errorMsg);
      }

      const result = await response.json();

      if (!result.summary) {
        notify(result.message || "Inga profiler att köra", { type: "info" });
        fetchProfiles();
        return;
      }

      const summary = result.summary;
      notify(
        `Klart! ${summary.profiles_processed} profiler körda: ${summary.total_new_leads} nya leads, ${summary.total_enriched} enrichade`,
        { type: "success" },
      );

      fetchProfiles();
    } catch (error) {
      notify(`Fel: ${(error as Error).message}`, { type: "error" });
    } finally {
      setIsRunning(null);
    }
  };

  const handleReEnrichAll = async () => {
    setIsRunning(-2);
    try {
      const {
        data: { session },
      } = await supabase.auth.getSession();

      if (!session) {
        notify("Du måste vara inloggad", { type: "error" });
        return;
      }

      const response = await fetch(
        `${import.meta.env.VITE_SUPABASE_URL}/functions/v1/auto_scrape`,
        {
          method: "POST",
          headers: {
            "Content-Type": "application/json",
            Authorization: `Bearer ${session.access_token}`,
          },
          body: JSON.stringify({ action: "re_enrich" }),
        },
      );

      if (!response.ok) {
        let errorMsg = `HTTP ${response.status}`;
        try {
          const errorBody = await response.json();
          errorMsg = errorBody.message || errorMsg;
        } catch {
          errorMsg = await response.text().catch(() => errorMsg);
        }
        throw new Error(errorMsg);
      }

      const result = await response.json();
      notify(
        `Klart! ${result.re_enriched} av ${result.total_candidates} företag enrichade (sociala medier, webbkvalité, Allabolag)`,
        { type: "success" },
      );
    } catch (error) {
      notify(`Fel: ${(error as Error).message}`, { type: "error" });
    } finally {
      setIsRunning(null);
    }
  };

  const formatDate = (dateStr?: string) => {
    if (!dateStr) return "Aldrig";
    return new Date(dateStr).toLocaleString("sv-SE", {
      month: "short",
      day: "numeric",
      hour: "2-digit",
      minute: "2-digit",
    });
  };

  return (
    <Dialog open={open} onOpenChange={setOpen}>
      <DialogTrigger asChild>
        <Button variant="outline" size="sm" className="gap-2">
          <Settings2 className="h-4 w-4" />
          Sökprofiler
        </Button>
      </DialogTrigger>
      <DialogContent className="max-w-4xl max-h-[90vh] overflow-y-auto">
        <DialogHeader>
          <DialogTitle>Automatiska sökprofiler</DialogTitle>
          <DialogDescription>
            Konfigurera vilka typer av företag som ska scrapes automatiskt.
            Varje profil söker efter en specifik bransch i en stad.
          </DialogDescription>
        </DialogHeader>

        {showForm && editingProfile ? (
          <div className="grid gap-4 py-4">
            <div className="grid grid-cols-2 gap-4">
              <div className="grid gap-2">
                <Label>Bransch *</Label>
                <Input
                  placeholder="t.ex. restauranger, frisörer, tandläkare"
                  value={editingProfile.branch}
                  onChange={(e) =>
                    setEditingProfile({
                      ...editingProfile,
                      branch: e.target.value,
                    })
                  }
                />
              </div>
              <div className="grid gap-2">
                <Label>Stad *</Label>
                <Input
                  placeholder="t.ex. Östersund, Stockholm"
                  value={editingProfile.city}
                  onChange={(e) =>
                    setEditingProfile({
                      ...editingProfile,
                      city: e.target.value,
                    })
                  }
                />
              </div>
            </div>

            <div className="grid grid-cols-2 gap-4">
              <div className="grid gap-2">
                <Label>Sökmall</Label>
                <Input
                  value={editingProfile.query_template}
                  onChange={(e) =>
                    setEditingProfile({
                      ...editingProfile,
                      query_template: e.target.value,
                    })
                  }
                />
                <p className="text-xs text-muted-foreground">
                  Använd {"{bransch}"} och {"{stad}"} som platshållare
                </p>
              </div>
              <div className="grid gap-2">
                <Label>Extra nyckelord (kommaseparerat)</Label>
                <Input
                  placeholder="t.ex. litet, nystartat"
                  value={editingProfile.extra_keywords.join(", ")}
                  onChange={(e) =>
                    setEditingProfile({
                      ...editingProfile,
                      extra_keywords: e.target.value
                        .split(",")
                        .map((s) => s.trim())
                        .filter(Boolean),
                    })
                  }
                />
              </div>
            </div>

            <div className="grid grid-cols-3 gap-4">
              <div className="grid gap-2">
                <Label>Min Google-betyg</Label>
                <Input
                  type="number"
                  min={0}
                  max={5}
                  step={0.5}
                  value={editingProfile.min_rating}
                  onChange={(e) =>
                    setEditingProfile({
                      ...editingProfile,
                      min_rating: Number(e.target.value),
                    })
                  }
                />
              </div>
              <div className="grid gap-2">
                <Label>Max resultat</Label>
                <Input
                  type="number"
                  min={1}
                  max={50}
                  value={editingProfile.max_results}
                  onChange={(e) =>
                    setEditingProfile({
                      ...editingProfile,
                      max_results: Number(e.target.value),
                    })
                  }
                />
              </div>
              <div className="flex items-end gap-4">
                <div className="flex items-center gap-2">
                  <Switch
                    checked={editingProfile.auto_enrich}
                    onCheckedChange={(checked) =>
                      setEditingProfile({
                        ...editingProfile,
                        auto_enrich: checked,
                      })
                    }
                  />
                  <Label>Auto-enrich</Label>
                </div>
              </div>
            </div>

            <div className="flex gap-2 justify-end">
              <Button
                variant="outline"
                onClick={() => {
                  setShowForm(false);
                  setEditingProfile(null);
                }}
              >
                Avbryt
              </Button>
              <Button onClick={handleSave}>Spara profil</Button>
            </div>
          </div>
        ) : (
          <div className="grid gap-4 py-4">
            <div className="flex gap-2">
              <Button
                size="sm"
                onClick={() => {
                  setEditingProfile({ ...DEFAULT_PROFILE });
                  setShowForm(true);
