  if (!company) return null;
  if (isPending) {
    return <p className="text-sm text-muted-foreground p-4">Laddar...</p>;
  }

  const details = data?.[0];

  if (editing || !details) {
    return (
      <CustomerDetailsForm
        companyId={company.id}
        details={details}
        onDone={() => {
          setEditing(false);
          refetch();
        }}
        onCancel={details ? () => setEditing(false) : undefined}
      />
