                  transform={(data: any) => {
                    const attendees = parseAttendees(data.attendee_emails);
                    return {
                      ...data,
                      status: data.status || "scheduled",
                      source: "crm",
                      meeting_provider: data.meeting_provider || "google_meet",
                      time_zone:
                        data.time_zone ||
                        Intl.DateTimeFormat().resolvedOptions().timeZone ||
                        "Europe/Stockholm",
                      starts_at: new Date(data.starts_at).toISOString(),
                      ends_at: new Date(data.ends_at).toISOString(),
                      attendees,
                      metadata: {
                        created_from: "calendar_page",
                      },
                    };
                  }}
                  mutationOptions={{
                    onSuccess: () => {
                      setIsCreateOpen(false);
                      notify("resources.calendar_events.added");
                    },
                  }}
                />
              </DialogFooter>
            </Form>
          </CreateBase>
        </DialogContent>
      </Dialog>

      {filterContactId ? (
        <Button asChild variant="ghost" size="sm" className="px-0">
          <Link to="/calendar">
            {translate("resources.calendar_events.action.create_new")}
          </Link>
        </Button>
      ) : null}
    </div>
  );
};

